INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1035685-ias212', 'stk-user6008', 'IAS 212', 'info', '{"desc": "كورس سهل خفيف يتكلم عن أخلاقيات المهنة بشكل عام\n\nالميجر الثاني كان من مذكرة خارج الكتاب\n\nالكورس بشكل عام رائع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-212-professional-ethics/120494/3", "user": "user6008", "ts": 1336714155000, "tid": 120494, "pn": 3}}', 1336714155000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1048247-ias212', 'stk-user5643', 'IAS 212', 'info', '{"desc": "اخلاقيات المهنه & الاخلاق في الاسلام\n\nالرشوه … الكبر … و صفات كثير\n\nكون انه اسلامي فـ غالبه حفظ … لكن سهل مره الحفظ", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-212-professional-ethics/120494/7", "user": "user5643", "ts": 1338411381000, "tid": 120494, "pn": 7}}', 1338411381000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1048251-ias212', 'stk-khalid2010', 'IAS 212', 'info', '{"desc": "سهل\n\nبس الي سمستر 112 كان المنهج كتابين شوي طويل\n\nبس الدكتور قال لنا ان القسم يدرس كتب جديده للماده و ان شاء الله تكون افضل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-212-professional-ethics/120494/8", "user": "khalid2010", "ts": 1338411578000, "tid": 120494, "pn": 8}}', 1338411578000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1139732-ias212', 'stk-abo_ali', 'IAS 212', 'info', '{"desc": "ترم 121\n\nجودة المقرر بشكل عام\nجميل احسن بألف مره من 111\n\nالمواضيع التي يغطيها المقرر\nالاخلاق الوظيفية والعمل والاخلاق الجيده والسلبيه ونظام الدوله في العمل وغيره\n\nالكتاب المستخدم للمقرر\nواضح\n\nالأسئلة والأمثلة المستخدمة في المقرر\nلووووول ماث على غفله ض1\n\nمدى فائدته في الناحية التطبيقية\nصفر على الشمال 😦", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-212-professional-ethics/120494/9", "user": "Abo_Ali", "ts": 1355407582000, "tid": 120494, "pn": 9}}', 1355407582000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1228895-ias212', 'stk-guest', 'IAS 212', 'info', '{"desc": "سمستر 122\nكتابين جدد للمادة ، كتاب من طباعة جامعة الملك عبدالعزيز بعنوان الثقافة الإسلامية ومنه متيريل ميجر 1 وميجر 2 والكتاب سقيم جداً جداً جداً، الكتاب الثاني من تأليف الدكتور عصام الحميدان ( عضو هيئة التدريس هنا بالجامعة ) والكتاب جميل وواضح ولغته سهلة ، الكورس سهل بشكل عام لكن في حفظ كثبر زي اي كورس اسلامي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-212-professional-ethics/120494/12", "user": "Guest", "ts": 1369679795000, "tid": 120494, "pn": 12}}', 1369679795000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1357520-ias212', 'stk-medoalkebsi', 'IAS 212', 'info', '{"desc": "الكتب المستخدمه 2 . واحد من جامعه الملك عبدالعزيز و الثاني من جامعتنا .\n\nالي من جامعه الملك عبدالعزيز جدآ حلو وممتاز , وافضل شي فيه السمري الي بكل اخر وحده .\n\nكتاب جامعتنا حلو .\n\nالكورس خفيف وسهل جدآ اسهل من 111.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-212-professional-ethics/120494/14", "user": "Medoalkebsi", "ts": 1398435445000, "tid": 120494, "pn": 14}}', 1398435445000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1390267-ias212', 'stk-user8581', 'IAS 212', 'info', '{"desc": "جودة المقرر بشكل عام & المواضيع التي يغطيها المقرر\nجيد … ويتكلم عن أخلاقيات المهنة وقوانين العمل في السعودية بالتحديد نظام الخدمة المدنية ونظام العمل .\n\nالكتاب المستخدم للمقرر\nفيه كتابين واحد لجامعة الملك عبدالعزيز وهو أفضل من الكتاب الثاني.\nوالثاني كتاب تبع الجامعة للدكتور عصام الحميدان.\n\nمدى فائدته في الناحية التطبيقية\nالصراحة اشوف مواد الإسلامي والعربي ما منها فايدة و الاستفادة منها تكون عن طريق الدكتور وطريقة شرحه للمواد مثل المناقشة او ربط المنهج بالواقع\n\nإضافات :\nنزل مع أكثر دكتور يعطي بونصات\nالكورس سهل لكن مب مثل سهولة عربي 201 لأن فيه شوي حفظ مثل كل مواد الاسلامي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-212-professional-ethics/120494/16", "user": "user8581", "ts": 1408219103000, "tid": 120494, "pn": 16}}', 1408219103000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1422830-ias212', 'stk-user10207', 'IAS 212', 'info', '{"desc": "المادة تتكلم عن الأخلاق والأخلاقيات في المهنة بالمملكة العربية السعودية.\nيوجد كتابين للمادة. الأول/ الثقافة الإسلامية والثاني/ أخلاقيات المهنة.\nفيها حفظ كثير. في الإختبارات الأسئلة تجي من بين السطور. مايركزون على الأشياء المهمة.\nالأولد اكزام مهم جداً ويجيبون اسئلة اختبارات قديمة.\nالكورس جداً سهل، لكن a+ مش سهلة. تحتاج أنك ماتغيب ولاتتأخر.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-212-professional-ethics/120494/18", "user": "user10207", "ts": 1437488012000, "tid": 120494, "pn": 18}}', 1437488012000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1526520-ias212', 'stk-user11724', 'IAS 212', 'info', '{"desc": "IAS212-TERM201\n\nالمادة بسيطة نوعا ما، فيها شغل اكثر من IAS111، فيه شرح درس لجزئية من الكتاب وفيه ملخص لكتاب تعرضه انت ومجموعتك وطبعا عليها درجات، الدكتور يأثر في التقييم ود. عبدالرحمن الخالدي مسهل الموضوع جدا خصوصا اننا في ترم اونلاين ذحين، الميجر الاول 15% والثاني 20% والفاينل 25% وفيه اسئلة مو قليلة تجي نصا من الاولد اقزام، ولازم يحطون سؤال ولا سؤالين ماتدري ايش وضعها، في النهاية حاول ما تقل عن الB+، الشغل فيها اسهل من التعليقات الي شباب قالوها وماحسيت بالضغط الي وصفوه، يمكن لانهم يبغون الاسلامي ما تسوي فيه شيء ابدا مثل IAS111، بالتوفيق للجميع.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-212-professional-ethics/120494/22", "user": "user11724", "ts": 1604558099000, "tid": 120494, "pn": 22}}', 1604558099000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527245-ias212', 'stk-user11942', 'IAS 212', 'info', '{"desc": "(Term201 (Online\n\nمادة تتحدث عن أخلاقيات المهنة كالإخلاص والأمانة والقوة وغيرها وكذلك القيم واختلافها عن مفهوم الأخلاق. وتطبيقاتها في الأنظمة السعودية. وفيه معلومات مفيدة جداً عن نظام العمل السعودي والخدمة المدنية وديوان المظالم.\n\nالكتاب المقرر : كتاب واحد- سابقاً كان كتابين- وعنوانه أخلاقيات المهنة في الإسلام وتطبيقاتها في أنظمة المملكة العربية السعودية للدكتور عصام الحميدان والدكتور يدرس الكورس أيضاً. والكتاب سيء جداً وعندي ملاحظات كثيرة عليه. مثلاً؛ توجد فيه إحصاءات ومعلومات كثيرة مبتورة المصدر. تكلم مثلاً عن ظاهرة اليوروكي (Yoruki) في اليابان ولم يذكر لها مصدر وعندما بحثت عنها بالعربي والانجلش لم أجد لها ذكر! وغيرها الكثير.\nوكذلك معلومات قديمة عن أنظمة ألغيت من الأصل فالكتاب يحتاج لتحديث وطبعة جديدة.\n\nوفي الفاينل عطونا مذكرة زيادة عن أخلاقيات مهنة الإعلام والمحاسبة.\n\nالكورس ككونسبت خفيف وفي حشو كثير في الكتاب. واللعب في المياجر يكون على المفردات والمفاهيم بمعنى لازم تعرف الفرق بين الرشوة والهدية وبين الحاجة والضرورة وبين العمل والمهنة والحرفة وهلم جرا. وكذلك أسئلة Case Study تلخبط شوي.\n\nفي المياجر والفاينل جابوا كثير أسئلة على شكل case study. والظاهر هذه سياستهم الجديدة في وضع الأسئلة ليس مثل السابق في السؤال عن المعلومة بشكل مباشر. وربما تتغير في الحضوري.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-212-professional-ethics/120494/23", "user": "user11942", "ts": 1608823479000, "tid": 120494, "pn": 23}}', 1608823479000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p886451-ias212', 'stk-mr-3b0d', 'IAS 212', 'info', '{"desc": "لإحقاق الحق\n\nكان أصعب من المياجر\n\nلكنه موب صعب\n\nترددت في 3-4 اسئلة علما ان مذاكرتي-قراءة- وما خلصت المنهج كامل+ما فتحت ماتيريال ميجر1+2", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/110802/4", "user": "mr-3b0d", "ts": 1313475921000, "tid": 110802, "pn": 4}}', 1313475921000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p623113-ias212', 'stk-the_champion', 'IAS 212', 'info', '{"desc": "95 وفوق a+\n90 وفوق a\n85 وفوق b+\n80 وفوق b\n75 وفوق c+\n70 وفوق c\n65 وفوق d+\n60 وفوق d\nاقل من 60 f\nهذا معنى ستاندرد عادي وهو النظام المتبع لمواد ias\nلكن ما يمنع ان دكتور من الدكاترة يساعد طلابه بدرجة او اكثر للوصول الى الجريد الافضل\nوبالتوفيييييييييييق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-212/89385/4", "user": "the_champion", "ts": 1275774679000, "tid": 89385, "pn": 4}}', 1275774679000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p840410-ias212', 'stk-the_marvel', 'IAS 212', 'info', '{"desc": "نفس الشي…\n\n211 المفروض 212\n\nهذا خطا في الخطة المفروض يعدلونه…\n\nبس شكلهم ما لاحظوا ولا احد كلمهم عن هالخطا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias211-ias212/107153/2", "user": "The_Marvel", "ts": 1304440101000, "tid": 107153, "pn": 2}}', 1304440101000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p358841-ias212', 'stk-user3270', 'IAS 212', 'srcU', '{"html": "يعطيك العافية يا قحطاني وهذي ايضا ملخضات اعطانياها الدكتور 🙂<br><br>بالتوفيق للجميع 🌹<br><br>​<span data-fid=\"stk-f358841-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f358841-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f358841-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f358841-0": {"name": "الأخلاق المذمومة.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/cd6ca7f71a8aecd0dc80bc80c55e1ecbe43a31e11d584ce135b614087f4e7f8a"}, "stk-f358841-1": {"name": "الأخلاق المهنية في الأنظمة السعودية.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/4146105e55aa0a723712da6cde845caf26601b4b93745879d3e9e62ca60ddd12"}, "stk-f358841-2": {"name": "المخالفات المهنية ووسائل التغلب عليها.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/932edacc9add030ebdad3d8161e1aa5d356f19ecc8ffd5a8b3d4a4d00b1cb848"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-212/69958/9", "user": "user3270", "ts": 1233447518000, "tid": 69958, "pn": 9}}', 1233447518000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p810772-ias212', 'stk-aflatoon', 'IAS 212', 'srcU', '{"html": "السلام عليكم ورحمة الله …<br>مساء الخير …<br><br>ياشباب فيه في مكتبة سديم (عند عمارة 827 )نوت لمذاكرة ias212 ميجر 1 …<br><br>فيها أهم الاشياء… وايضا فيها اغلب اسئلة الاولد اقزام …<br>والاشياء اللي عليها علامة ( / ) قد جت في اختبارت سابقة …<br><br>موفقين ياشباب … دعواتكم …<br><br>النوت باسم : أبو محمد ias212<br><br>*قد يكون الخط غير واضح … فأعتذر عن ذلك …<br>*ماكان من صواب فمن الله … وماكان من خطأ فمن نفسي والشيطان", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-212/104553/1", "user": "AFLATOON", "ts": 1299772066000, "tid": 104553, "pn": 1}}', 1299772066000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p965170-ias212', 'stk-27mansour', 'IAS 212', 'srcP', '{"html": "س1: عمل النبي صلى الله عليه وسلم قبل نبوَّته في:<br>التجارة.<br><br>س2: التكسُّب والعمل مشروع، هو قول:<br>إجماع العلماء.<br><br>س3: تعريف الأخلاق(حال للنفس داعية لها إلى أفعالها من غير فكرة ولا رويَّة) هو تعريف:<br>مسكويه.<br><br>س4: التعريف اللغوي لها: ما يقدَّر من عمل أو طعام أو رزق وغير ذلك في زمن معيَّن ، وتأتي بمعنى الخدمة المعيَّنة. هي:<br>الوظيفة.<br><br>س5: الفرق بين تعريف الإدارة الإسلامية و تعريف الإدارة البحتة:<br>أن الإدارة الإسلامية تربط الإدارة بالغاية التي يعيش لها المسلم وهي عبادة الله تعالى.<br><br>س6: حقق يوسف عليه السلام الأمن الاقتصادي لمصر أنجاها من الكارثة، وهو في الإدارة عنصر:<br>التخطيط.<br><br>س7: قوله صلى الله عليه وسلم ( لعن الله اليهود، حرم الله عليهم الشحوم، فجملوها ( أذابوها ) فباعوها ) استدل به المؤلف على:<br>أن الله إذا حرم شيئاً حرم ثمنه.<br><br>س8: حرم الله الخمر مع أن فيها منافع للناس؛ لأن:<br>العبرة بالغالب.<br><br>س9: قال صلى الله عليه وسلم(يطبع المؤمن على كل خلة غير):<br>الخيانة والكذب.<br><br>س10: الأذى في الصدقة أخف من الأذى في حقوق الآخرين:<br>لأن الصدقة مبنية على المسامحة.<br><br>س11: حكم كتمان العلم:<br>حرام بشروط.<br><br>س12: حكم السطو على الكتب والبحوث محفوظة الحقوق:<br>حرام.<br><br>س13: للعدل ثلاث تعريفات شرعاً: إعطاء كل ذي حق حقه من غير إفراط أو تفريط. أو: بذل الحقوق الواجبة وتسوية المستحقين في حقوقهم، أو: فصل الحكومة على ما في الكتاب والسنة لا بالرأي المجرَّد، الأصح منها:<br>الأول.<br><br>س14: أظلم الظلم الشرك، ثم:<br>من افترى على الله الكذب.<br><br>س15: أهم خلقين يحتاجهما الموظف:<br>القوة والأمانة.<br><br>س16: قوله تعالى(إذْ قَالَ لَهُ قَوْمُهُ لَا تَفْرَحْ إِنَّ اللَّهَ لَا يُحِبُّ الْفَرِحِينَ) يعني:<br>فرح الكبر.<br><br>س17: إذا كتب المهندس أن المشروع مستوفٍ للشروط وهو ليس كذلك، فهو:<br>غشّ.<br><br>س18: اليوروكي هو:<br>نزعة نفسية للإحساس بالذات من خلال العمل عند اليابانيين.<br><br>س19: لا يجوز التأخُّر عن الدوام ، لذا إذا تأخر الموظف عن الدوام فعليه أن:<br>يعوِّض ذلك بوقتٍ إضافي، أو عملٍ إضافي يقدّمه للعمل.<br><br>س20: إضرار الموظف بالمصلحة العامة فـي ميدان الصفقات والمقاولات والتوريدات، صورة من صور:<br>استغلال الوظيفة.<br><br>س21: حفظ السر فرع من فروع:<br>الأمانة.<br><br>س22: إذا اقتضت مصلحة العمل إفشاء السر كتدريب موظف جديد على مباشرة مهام الوظيفة فحكم إفشاء السر:<br>جائز.<br><br>س23: في قوله سبحانه (يَا أَيُّهَا الَّذِينَ آمَنُواْ أَطِيعُواْ اللّهَ وَأَطِيعُواْ الرَّسُولَ وَأُوْلِي الأَمْر) لماذا لم يكرر لفظ الطاعة مع أولي الأمر؟<br>لأنها مرتبطة بطاعة الله ورسوله.<br><br>س24: القرآن الكريم نبَّه إلى الحذر من الهدايا التي يقصد به الرشوة في قصة:<br>سليمان عليه السلام.<br><br>س25: دفع المبالغ المالية للموظف مقابل قضاء مصلحة المراجع، إذا كانت هذه المصلحة ليست من صميم عمل الموظف:<br>لا تعتبر رشوة.<br><br>س26: استدل المؤلف بقوله سبحانه( مَّن يَشْفَعْ شَفَاعَةً حَسَنَةً يَكُن لَّهُ نَصِيبٌ مِّنْهَا وَمَن يَشْفَعْ شَفَاعَةً سَيِّئَةً يَكُن لَّهُ كِفْلٌ مِّنْهَا وَكَانَ اللّهُ عَلَى كُلِّ شَيْءٍ مُّقِيتاً) على:<br>الواسطة الحسنة.<br><br>س27: المبدأ الإسلامي في محاسبة المسؤولين هو مبدأ:<br>من أين لك هذا؟<br><br>س28: الوظيفة الأهلية يحكمها:<br>نظام العمل.<br><br>س29: إذا ثبت اتباع العامل سلوكاً سيئاً ، أو ارتكابه عملاً مخلاً بالشرف أو الأمانة:<br>يجوز فسخ العقد دون مكافأة.<br><br>س30: الهيئة الهندسية المقرة من مجلس الوزراء هي:<br>الهيئة السعودية للمهندسين.<br><br>يتبع …", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias212/118021/1", "user": "27Mansour", "ts": 1326334404000, "tid": 118021, "pn": 1}}', 1326334404000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1237054-ias212', 'stk-guest', 'IAS 212', 'srcP', '{"html": "مشكووووووور وتسلم يدك 🌹<br>لكن متأكد ان نفس المقرر؟؟ يعني نفس الصفحات الي علينا ؟ ولا تختلف<br>عالعموم هذي هي الاسئله الي فالرابط:<br>=========<br>س1/<br>من الأدلة التي تدل على صلة الأخلاق بالإيمان<br>- الجواب: أ: قوله صلى الله عليه وسلم ( لا إيمان لمن لا امانة له )<br><br>أ: قوله صلى الله عليه وسلم ( لا إيمان لمن لا امانة له )<br>ب: قوله تعالى \" وما خلقتُ الجنَّ والإنسَ إلا ليعبدون \"<br>ج: قوله تعالى \" إن الصلاة تنهى عن الفحشاء و المنكر \"<br>د: جميع ما سبق<br><br>س2/<br>في قوله صلى الله عليه وسلم ( لا يفرُك -أي يبغض- مؤمن مؤمنة إن كرهَ منها خلقاً رضيَ منها آخر )<br>الجواب: أ: حث المسلم على الانتباه للنظر إلى المحاسن وعدم التركيز على المساوئ<br><br>أ: حث المسلم على الانتباه للنظر إلى المحاسن وعدم التركيز على المساوئ<br>ب: النهي عن طلاق الرجل للمرأة<br>ج: النهي عن ضرب المرأة<br>د: جميع ما سبق<br>هـ: لا شيء مما سبق<br><br>س3/<br>استدل المقرّر بقوله ( البر حسن الخلق و الإثم ما حاك في صدرك و كرهتَ أن يطّلعَ عليه الناس ) على:<br>الجواب: ب: هناك أخلاق مكتسبة<br><br>أ: هناك أخلاق فطرية و جبليّة<br>ب: هناك أخلاق مكتسبة<br>ج: الإنسانية و الفطريّة محفّز من محفّزات الأخلاق<br>د: السلوك العملي من أبرز الدلائل على خلق الإنسان<br>هـ: لا شيء مما سبق<br><br>- الجواب الذي نقلته عن الدكتور هو ( ب )، رغم اني شاك … ممكن يكون الجواب ( أ ) ، إخلاءً للمسؤولية راجعوا الكتاب صـ 58 ـ<br><br>س4/<br>ربانية الأخلاق إحدى خصائص الأخلاق في الإسلام ومعناها أن:<br>الجواب: ب: أن الاخلاق ليست من نتاج الفكر البشري بل تشريع من الله<br><br>أ: الله يجازي عباده على تمسكهم بالأخلاق<br>ب: أن الاخلاق ليست من نتاج الفكر البشري بل تشريع من الله<br>ج: أن الأخلاق يتربى عليها المجتمع<br>د: جميع ما سبق<br>هـ: ب + ج<br><br>س5/<br>حقيقة الأخلاق في اللغة:<br>الجواب: أ: ما يأخذ به الإنسان نفسه من الأدب<br><br>أ: ما يأخذ به الإنسان نفسه من الأدب<br>ب: ما يأخذ به الإنسان نفسه من العمل<br>ج: ما يأخذ به الإنسان نفسه من القوة<br>د: ما يأخذ به الإنسان نفسه من الحق<br><br>س6/<br>مزايا ارتباط الإيمان بالأخلاق:<br>الجواب:هـ: جميع ما سبق<br><br>أ: قدسية الأخلاق<br>ب: استقرار وثبات الأخلاق<br>ج: الترابط بين السلوك الأخلاقي والسعادة النفسية<br>د: التجرد في الممارسة الخلقية تعلقا بالمثوبة الأخروية<br>هـ: جميع ما سبق<br><br>س7/<br>من مزايا وجود الصلة والعلاقة بين المعاملات والأخلاق:<br>الجواب: هـ: أ + ب<br><br>أ: رفع كفاءة الإنتاج في الأجواء الأخلاقية<br>ب: إنسانية وأخلاقية معايير النجاح وأن الأخلاق جزء من معايير النجاح<br>ج: التجرد من ممارسة الأخلاق تعلقا بالدار الآخرة<br>د: جميع ما سبق<br>هـ: أ + ب<br><br>س8/<br>استدل المقرر بقوله تعالى \" ولقد كرمنا بني آدم \"<br>الجواب: د: مفهوم الأخلاق الإنساني و الحضاري من جهة تكريم الله للإنسان<br><br>أ: بيان كيفية تطبيق الأخلاق في الحياة<br>ب: بيان عدم تعدي الإنسان على بني آدم<br>ج: بيان علاقة الإنسان العظيمة ببني آدم<br>د: مفهوم الأخلاق الإنساني و الحضاري من جهة تكريم الله للإنسان<br><br>س9/ النموذجية في الأخلاق<br>الجواب: ب: إحدى خصائص الأخلاق<br><br>أ: إحدى محفزات الأخلاق<br>ب: إحدى خصائص الأخلاق<br>ج: إحدى مظاهر ودلائل الأخلاق<br>د: إحدى أنواع الأخلاق<br>هـ: إحدى مزايا الأخلاق<br><br>س10/<br>الخلق متعلق بالخصال والخلال المدركة بالبصيرة<br>الجواب: أ: صواب<br><br>أ: صواب<br>ب: خطأ<br><br>س11/<br>استدل المقرر بقوله تعالى { ورهبانية ابتدعوها ما كتبناها عليهم } على:<br>الجواب أ: الإسلام جاء بالدعوة إلى الانسجام مع الفطرة البشرية وعدم معارضة طبيعة الإنسان<br><br>أ: الإسلام جاء بالدعوة إلى الانسجام مع الفطرة البشرية وعدم معارضة طبيعة الإنسان<br>ب: سماحة الإسلام<br>ج: ذم الحضارات الأخرى وبيان خللها في فهم الحياة<br>د: شمولية الأخلاق الإسلامية<br>هـ: تحريم الأخلاق المذمومة<br><br>س12/<br>من مزايا ارتباط الأخلاق بالعبادات حضور وتأثير العنصر العاطفي كالخشوع ولذة المناجاة لله في البناء الأخلاقي المسلم<br>الجواب: أ: صواب<br><br>أ: صواب<br>ب: خطأ<br><br>س13/<br>من أوجه ارتباط الأخلاق بالمسؤولية و الجزاء في الدنيا والآخرة<br>الجواب: هـ: أن الأخلاق أوامر ربانية و تكاليف شرعية<br><br>أ: أن الأخلاق على صلة بالإيمان<br>ب: أن الأخلاق على صلة بالعبادات<br>ج: أن الأخلاق على صلة بالأحوال الشخصية<br>د: أن الأخلاق على صلة بالعلاقات الاجتماعية<br>هـ: أن الأخلاق أوامر ربانية و تكاليف شرعية<br><br>س14/<br>أبرز معالم و سمات الخُلُق الحقيقية<br>الجواب: هـ: جميع ما سبق<br><br>أ: الخلق أساسه صفة نفسية و معنوية<br>ب: الخلق صفة راسخة مستقرة وليست عارضة<br>ج: الخلق طبع تلقائي<br>د: الخلق له آثار عملية في الأقوال و الأفعال<br>هـ: جميع ما سبق<br><br>س15/<br>النموذجية في الأخلاق معناها<br>الجواب: ب: الأخلاق الإسلامية ليست مجرد تنظير بل هي واقعية مع أنها مبادئ طموحة و كبيرة<br><br>أ: الأخلاق الإسلامية أخلاق مثالية<br>ب: الأخلاق الإسلامية ليست مجرد تنظير بل هي واقعية مع أنها مبادئ طموحة و كبيرة<br>ج : الأخلاق الإسلامية تعتبر نظاما متكاملاً<br>د: الأخلاق الإسلامية مصدرها من الله تعالى<br><br>س16/<br>القدوة الحضارية<br>الجواب: د: جميع ما سبق<br><br>أ: أحد العوامل المحفزة للأخلاق<br>ب: إحدى خصائص الأخلاق الإسلامية<br>ج: إحدى مظاهر ودلائل الأخلاق<br>د: جميع ما سبق<br><br>س17/<br>المؤرخ أتومنبي ( الاسم مشكووك فييه - برجاء المراجعة و التصحيح - ) يرى أن انعدام الأخلاق في مجتمع من المجتمعات سبب في:<br>الجواب: أ: انهيار المجتمع بأكمله<br><br>أ: انهيار المجتمع بأكمله<br>ب: انهيار المجتمع في الجانب العسكري<br>ج: ليس له دخل في سقوط الحضارات<br>د: لا شيء مما سبق<br><br>س18/<br>جاء الإسلام ليبين للإنسان الأحكام والأوامر المتصلة لعلاقته بجانبين: 1- علاقة الإنسان مع الخالق 2- علاقة الإنسان مع المخلوق<br>الجواب: أ: صواب<br><br>أ: صواب<br>ب: خطأ<br><br>س19/ التعريف المختار للخلُق<br>الجواب: ب: قوة راسخة في النفس تنزع بها \" بسهولة ودون تكلف \" إلى اختيار الخير \" أو \" الشر بضابط الشرع الحنيف والفطرة السليمة وتظهر آثارها في الأقوال والأفعال والأحوال<br><br>أ: قوة راسخة في النفس تنزع بها بتكلف ومشقة إلى اختيار الخير والشر بضابط الشرع الحنيف والفطرة السليمة وتظهر آثارها في الأقوال والأفعال والأحوال<br>ب: قوة راسخة في النفس تنزع بها بسهولة ودون تكلف إلى اختيار الخير أو الشر بضابط الشرع الحنيف والفطرة السليمة وتظهر آثارها في الأقوال والأفعال والأحوال<br>ج: قوة راسخة في النفس تنزع بها بتكلف ومشقة إلى اختيار الخير دون الشر بضابط الشرع الحنيف والفطرة السليمة وتظهر آثارها في الأقوال والأفعال والأحوال<br>د: لا شيء مما سبق<br><br>س20/<br>للإسلام أحكام كثيرة تدل على ارتباط الأخلاق بالمعاملات<br>الجواب: د: جميع ما سبق<br><br>أ: النهي عن التطفيف<br>ب: النهي عن بيع المسلم على بيع أخيه<br>ج: الأمر بالعدل و عدم الظلم أثناء البيع<br>د: جميع ما سبق<br><br>س21/<br>الشمولية في الأخلاق الإسلامية أحد مظاهر و دلائل الأخلاق<br>الجواب: ب: خطأ<br><br>أ: صواب<br>ب: خطأ<br><br>س22/<br>ميل الإنسان الفطري إلى الخلق الحسن<br>الجواب: ج: يقود النفس الإنسانية لحب الخير و النفرة من الشر ويجعل الأخلاق شكلاً من أشكال الوعي الإنساني<br><br>أ: يفقد الأخلاق قيمتها<br>ب: لا يؤثر في الأخلاق سلباً و إيجاباً<br>ج: يقود النفس الإنسانية لحب الخير و النفرة من الشر ويجعل الأخلاق شكلاً من أشكال الوعي الإنساني<br>د: جميع ما سبق<br><br>س23/<br>استدل المقرر بقوله { لن ينال الله لحومها ولا دمائها } على<br>الجواب: د: أ + ب<br><br>أ: الصلة بين الأخلاق و الحج<br>ب: استغناء الله عن عباده<br>ج: تأكيد طاعة الله<br>د: أ + ب<br><br>س24/<br>التربية و المسؤولية<br>الجواب: أ: أحد محفزات الأخلاق<br><br>أ: أحد محفزات الأخلاق<br>ب: أحد خصائص الأخلاق<br>ج: أحد مظاهر ودلائل الأخلاق<br>د: أحد أنواع الأخلاق<br>هـ: أحد مزايا الأخلاق<br><br>س25/<br>استدل المقرر بقوله تعالى { وما كان ربك ليهلك القرى بظلم و أهلها مصلحون } على<br>الجواب: ب: الفساد الأخلاقي سبب في سقوط الحضارات<br><br>أ: الإنسان هو الذي يبني الحضارة<br>ب: الفساد الأخلاقي سبب في سقوط الحضارات<br>ج: النهي عن الإفساد في الأرض<br>د: جميع ما سبق<br><br>س26/<br>أبرز ما يدل على أخلاق الإنسان<br>الجواب: هـ: جميع ما سبق<br><br>أ: الكلام<br>ب: السلوك العملي<br>ج: المظهر الخارجي<br>د: الصاحب و الصديق<br>هـ: جميع ما سبق<br><br>س27/<br>تعريف الخلق بأنه: عبارة عن هيئة للنفس راسخة تصدر عنها الأفعال بسهولة ويسر من غير حاجة إلى فكر و روية. فإن كانت الهيئة بحيث تصدر عنها الأفعال الجميلة عقلاً و شرعاً بسهولة، سميت الهيئة: خلقاً حسناً. وإن كان الصادر منها الأفعال القبيحة، سميت الهيئة: خلقا سيئا.<br>سبب القصور في هذا التعريف أنه:<br><br>الجواب: ب: أنه يجعل الأخلاق مقتصرة على الجانب الفطري<br><br>أ: أنه يجعل الأخلاق مقتصرة على الجانب الإرادي<br>ب: أنه يجعل الأخلاق مقتصرة على الجانب الفطري<br>ج: …<br>د: …<br>- الخيارين \" ج \" و \" د \" ما كتبتها، - عذراً - ، ولكن الجواب هو ( ب ) سبب قصور التعريف أنه جعل الأخلاق مقتصرة على الجانب الفطري، راجع الكتاب صفحة 16 ـ<br><br>س28/<br>الزكاة في الأخلاق<br>الجواب: د: أ + ب<br><br>أ: تطهر النفس<br>ب: تغرس في النفس حب الخير و خلق الجود والكرم<br>ج: تكليف رباني<br>د: أ + ب<br><br>س29/ الانسجام في الأخلاق معناه:<br>الجواب: ج: متوافقة مع الفطرة وليست مناقصة لها<br><br>أ: الأخلاق شاملة<br>ب: مصدرها من الله<br>ج: متوافقة مع الفطرة وليست مناقصة لها<br>د: جميع ما سبق<br><br>س30/<br>قوله صلى الله عليه وسلم ( دع ما يريبك إلى ما لا يريبك )<br>دليل على أن الأخلاق تمثل استقراراً نفسياً و معياراً سلوكياً للفرد<br>الجواب: أ: صواب<br><br>أ: صواب<br>ب: خطأ", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-212/146339/2", "user": "Guest", "ts": 1371842583000, "tid": 146339, "pn": 2}}', 1371842583000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1431674-ias212', 'stk-f.torres', 'IAS 212', 'srcP', '{"html": "الاختبار النصفي لمادة أخلاقيات المهنة 212 للفصل الدراسي الأول (131) العام 1434-1435هـ<br><br>الشعبة الأستاذ اليوم من إلى الشعبة الأستاذ اليوم من إلى<br>6 hasan sendi ut 0700 0750 24 al-mashookhy ut 1100 1150<br>16 hasan sendi ut 0800 0850 25 al-mashookhy ut 1310 1400<br>17 hasan sendi mw 0800 0850 27 al-mashookhy mw 1000 1050<br>20 hasan sendi ut 1000 1050 28 al-mashookhy mw 1100 1150<br>22 hasan sendi mw 0700 0750 29 al-mashookhy mw 0900 0950<br>3 al-humaidan mw 0900 0950 32 al-mashookhy ut 1000 1050<br>8 al-humaidan tr 1000 1050 7 yahya alzahrani ut 1310 1400<br>9 al-humaidan mw 0800 0850 10 yahya alzahrani mw 1410 1500<br>11 al-humaidan tr 0900 0950 13 yahya alzahrani mw 1100 1150<br>12 al-humaidan tr 0800 0850 19 yahya alzahrani mw 1520 1610<br>1 khalid al-muzeini ut 0900 0950 21 yahya alzahrani mw 1000 1050<br>2 khalid al-muzeini ut 1000 1050 26 yahya alzahrani ut 1410 1500<br>15 khalid al-muzeini ut 0800 0850 30 yahya alzahrani ut 1520 1610<br><br>1 حقيقة الخُلق في اللغة: 2 يرى ابن خلدون أن طور الانهيار في الحضارات هو :<br>A ما يأخذ الإنسان به نفسه من الأدب. A فقدان القوة الاقتصادية.<br>B هيئة للنفس راسخة تصدر عنها الأفعال بسهولة من غير حاجة إلى فكر وروية. B الإسراف والتبذير واصطناع قرناء السوء.<br>C الهيئة والصفة المدركة بالبصر. C غلبة أهل الفساد على أهل الصلاح.<br>D صفة نفسية مستقرة ذات آثار في السلوك. D الهزيمة النفسية والعسكرية.<br><br>3 كان نبينا ïپ¥ خلُقه القرآن، ومعنى ذلك: 4 قول نبينا ïپ¥: (من كان يؤمن بالله واليوم الآخر فلا يؤذ جاره) فمن آذى جاره كان:<br>A أن إيمانه ïپ¥ عظيم وعبادته راسخة. A فاقد الإيمان.<br>B أنه ïپ¥ يكثر من قراءة القرآن والقيام به في الليل. B كامل الإيمان.<br>C أن امتثال القرآن صار سجية له ïپ¥ وخلقاً تطبَّعه. C ناقص الإيمان.<br>D أنه ïپ¥ يكثر من الاستشهاد بالقرآن. D جاحد الإيمان.<br><br>5 من مزايا قوة الصلة بين الإيمان والأخلاق: 6 من ترك المراء وإن كان محقا فإنه يستحق بيتا في :<br>A حضور العنصر العاطفي في البناء الأخلاقي. A ربض الجنة .<br>B إيجابية العلاقات الإنسانية. B وسط الجنة .<br>C رفع كفاءة الإنتاج. C أعلى الجنة .<br>D الترابط بين السلوك الأخلاقي والسعادة النفسية. D الفردوس الأعلى .<br><br>7 جاء في الحديث النبوي: (ألا أخبركم بأهل النار : كل عتل جواظ مستكبر) ومعنى العتل : 8 قال تعالى ï€©خُذْ مِنْ أَمْوَالِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِمْ بِهَاï€¨ والمقصود بالتزكية هنا إشارة إلى مقام:<br>A البخيل. A التحلية بالفضائل والحسنات.<br>B العاق. B التخلية من السيئات.<br>C الجافي الشديد الخصومة في الباطل. C زيادة المال فقط.<br>D الكذاب . D التخلص من الآفات الحسية.<br><br>9 من مظاهر العناية بالأخلاق في العصر الحديث ظهور جمعيات مهنية متخصصة عززت أخلاقيات العمل وذلك من خلال: 10 تتضمن مواثيق أخلاقيات المهنة فيما يتعلق بمعايير الأداء المثالي في المهنة ثلاثة أقسام وهي:<br>A إصدار القوانين والأنظمة التي تحاسب المخطئ أخلاقياً . A الشروط التأهيلية للمهنة، ومواصفات الأداء المثالي، والممارسات الخاطئة للمهنة .<br>B إصدار مواثيق تنظيمية وأخلاقية تتعلق بمهنتها . B الشروط التأهيلية للمهنة، والشروط النظرية، والشروط التكميلية .<br>C إصدار رخصة العمل المهنية . C الشروط التأهيلية للمهنة، والشروط الخاصة بمؤهلات الموظف، والشروط الخاصة بالبيئة .<br>D ضبط المخالفات المهنية وإحالتها للقضاء. D الشروط التأهيلية للمهنة، وأخلاق التعامل الإنساني، والشروط الخاصة بالبيئة .<br><br>11 من مؤسسات المجتمع المدني التي تعتني بأخلاق العمل: 12 جاء في ميثاق إحدى المهن ما يلي: (لا يجوز له أن يتحدث عن زميل له، أو يعرض به، أو ينسب إليه ما يحط من قدره، أو يشكك في مقدرته وعلمه): فما المهنة التي ورد فيها:<br>A وزارة العمل. A ميثاق المهنة لجمعية المحامين الكويتيين.<br>B جمعية حماية المستهلك. B ميثاق المهنة للأطباء السعوديين.<br>C المحاكم العامة. C ميثاق المهنة لموظفي مصلحة الضرائب المصرية.<br>D المجلس البلدي . D ميثاق المهنة للمهندسين الأمريكيين.<br><br>13 من مواصفات ومزايا مواثيق أخلاقيات المهنة: أن يستوعب الميثاق التخصصات التابعة للمهنة، ويكون مقسماً إلى أقسام وأبواب تتعلق بالشرائح المختلفة للمهنة، وهذا ما يسمى ميزة: 14 تطبيق النظام العشري للموازين والمقاييس وفحص ومراقبة أجهزة الوزن والقياس من مهام:<br>A الاختصار والتركيز . A هيئة المواصفات والمقاييس.<br>B الشمول والتصنيف . B وزارة التجارة و الصناعة.<br>C الخلقية والعلمية . C وزارة الشؤون البلدية و القروية.<br>D الالتزام والعقوبات . D وزارةالصحة.<br><br>15 مراقبة الصناع وأرباب الحرف من مهام الحسبة في الجانب: 16 يستند مذهب مكيافيلي إلى مبدأ:<br>A الديني. A الغاية تبرر الوسيلة الشريفة.<br>B الاقتصادي. B الغاية تبرر الوسيلة مهما كانت الوسيلة.<br>C المدني. C الوسيلة الدنيئة لا تبرر الغاية.<br>D الجنائي. D الغايات غير مرتبطة بالوسائل.<br><br>17 (مجموعة من المزايا والخصائص الخاصة بالمنتج أو الخدمة والتي تساهم في إشباع رغبات المستهلكين وتتضمن السعر والتوفر والموثوقية والأمان والاعتمادية وقابلية الاستعمال) العبارة السابقة تعريف:<br>A إدارة الجودة. C الجودة اصطلاحاً.<br>B السلوك العملي. D محفزات أخلاق المهنة.<br>الرقم العبارة العلامة<br>18 الخُلق أساسه صورة حسية لسلوكيات عملية. B<br>19 الإيمان ليس معان نظرية فقط، ولكن له آثار عملية سلوكية. A<br>20 الارتباط بين العقيدة والأخلاق يؤكده بعض المفكرين غير المسلمين. A<br>21 من مزايا قوة الصلة بين العبادات والأخلاق اقتصار الحضور الأخلاقي على الفرد. B<br>22 نهى رسول الله صلى الله عليه وسلم عن بيع النجش لما يترتب عليه من إثارة الأحقاد , والنجش يعني إخفاء العيب في السلعة . B<br>23 من مزايا قوة الصلة بين المعاملات والأخلاق رفع كفاءة الإنتاج . A<br>24 إن الكذب لا يحل في الجد ، ولا بأس به في الهزل. B<br>25 الخُلق الفاضل يجعل سلوك صاحبه مرناً غير ثابت ولا متماسك . B<br>26 كانت الكفاءة هي الشيء الوحيد الذي تهتم به الشركات، وأصبحت اليوم الأخلاق محل اهتمامها أيضا . A<br>27 وضعت الهيئة الملكية للجبيل وينبع برنامجاً متكاملاً لحماية البيئة . A<br>28 عاملان أساسيان يوضحان أن أخلاق المهنة من مزايا الحضارة الإسلامية ، أحدهما تحكيم القوانين والأنظمة الوضعية في واقع الحياة. B<br>29 من آداب المحتسب أن يأمر وينهى في العلن ليكون أبلغ في الموعظة والنصيحة. B<br>30 أخلاق المهنة في الإسلام مبدئية ويقصد بذلك أنها تستند إلى مبادئ راسخة وأسس ثابتة. A<br><br>انتهت الأسئلة .<br>أساتذة المادة يتمنون لك التوفيق ويدعون لك بالنجاح .", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/old-exams-ias212-143-142-141-131-132-133/170592/3", "user": "F.TORRES", "ts": 1446314572000, "tid": 170592, "pn": 3}}', 1446314572000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p764306-ias212', 'stk-user6441', 'IAS 212', 'srcP', '{"html": "هذا فاينل 93 ---212<br><br>س1: عمل النبي صلى الله عليه وسلم قبل نبوَّته في:.bالتجارة.<br>س2: التكسُّب والعمل مشروع، هو قول:.aإجماع العلماء.<br>س3: تعريف الأخلاق(حال للنفس داعية لها إلى أفعالها من غير فكرة ولا رويَّة) هو تعريف:.aمسكويه.<br>س4: التعريف اللغوي لها: ما يقدَّر من عمل أو طعام أو رزق وغير ذلك في زمن معيَّن ، وتأتي بمعنى الخدمة المعيَّنة. هي: .bالوظيفة. س5: الفرق بين تعريف الإدارة الإسلامية و تعريف الإدارة البحتة: .bأن الإدارة الإسلامية تربط الإدارة بالغاية التي يعيش لها المسلم وهي عبادة الله تعالى.<br>س6: حقق يوسف عليه السلام الأمن الاقتصادي لمصر أنجاها من الكارثة، وهو في الإدارة عنصر:.b التخطيط.<br>س7: قوله صلى الله عليه وسلم ( لعن الله اليهود، حرم الله عليهم الشحوم، فجملوها ( أذابوها ) فباعوها ) استدل به المؤلف على:<br>.aأن الله إذا حرم شيئاً حرم ثمنه.<br>س8: حرم الله الخمر مع أن فيها منافع للناس؛ لأن:.b العبرة بالغالب.<br>س9: قال صلى الله عليه وسلم(يطبع المؤمن على كل خلة غير… ).aالخيانة والكذب.<br>س10: الأذى في الصدقة أخف من الأذى في حقوق الآخرين:.bلأن الصدقة مبنية على المسامحة.<br>س11: حكم كتمان العلم:.cحرام بشروط.<br>س12: حكم السطو على الكتب والبحوث محفوظة الحقوق:.bحرام.<br>س13: للعدل ثلاث تعريفات شرعاً: إعطاء كل ذي حق حقه من غير إفراط أو تفريط. أو: بذل الحقوق الواجبة وتسوية المستحقين في حقوقهم، أو: فصل الحكومة على ما في الكتاب والسنة لا بالرأي المجرَّد، الأصح منها:.aالأول.<br>س14: أظلم الظلم الشرك، ثم:.cمن افترى على الله الكذب.<br>س15: أهم خلقين يحتاجهما الموظف:.aالقوة والأمانة.<br>س16: قوله تعالى(إذْ قَالَ لَهُ قَوْمُهُ لَا تَفْرَحْ إِنَّ اللَّهَ لَا يُحِبُّ الْفَرِحِينَ) يعني:.bفرح الكبر.<br>س17: إذا كتب المهندس أن المشروع مستوفٍ للشروط وهو ليس كذلك، فهو:.aغشّ.<br>س18: اليوروكي هو:.cنزعة نفسية للإحساس بالذات من خلال العمل عند اليابانيين.<br>س19: لا يجوز التأخُّر عن الدوام ، لذا إذا تأخر الموظف عن الدوام فعليه أن:.cيعوِّض ذلك بوقتٍ إضافي، أو عملٍ إضافي يقدّمه للعمل.<br>س20: إضرار الموظف بالمصلحة العامة فـي ميدان الصفقات والمقاولات والتوريدات، صورة من صور:.aاستغلال الوظيفة.<br>س21: حفظ السر فرع من فروع:.cالأمانة.<br>س22: إذا اقتضت مصلحة العمل إفشاء السر كتدريب موظف جديد على مباشرة مهام الوظيفة فحكم إفشاء السر:.aجائز.<br>س23: في قوله سبحانه (يَا أَيُّهَا الَّذِينَ آمَنُواْ أَطِيعُواْ اللّهَ وَأَطِيعُواْ الرَّسُولَ وَأُوْلِي الأَمْر) لماذا لم يكرر لفظ الطاعة مع أولي الأمر؟<br>.bلأنها مرتبطة بطاعة الله ورسوله.<br>س24: القرآن الكريم نبَّه إلى الحذر من الهدايا التي يقصد به الرشوة في قصة:.aسليمان عليه السلام.<br>س25: دفع المبالغ المالية للموظف مقابل قضاء مصلحة المراجع، إذا كانت هذه المصلحة ليست من صميم عمل الموظف:.bلا تعتبر رشوة.<br>س26: استدل المؤلف بقوله سبحانه( مَّن يَشْفَعْ شَفَاعَةً حَسَنَةً يَكُن لَّهُ نَصِيبٌ مِّنْهَا وَمَن يَشْفَعْ شَفَاعَةً سَيِّئَةً يَكُن لَّهُ كِفْلٌ مِّنْهَا وَكَانَ اللّهُ عَلَى كُلِّ شَيْءٍ مُّقِيتاً) على:.aالواسطة الحسنة.<br>س27: المبدأ الإسلامي في محاسبة المسؤولين هو مبدأ:.cمن أين لك هذا؟<br>س28: الوظيفة الأهلية يحكمها:.bنظام العمل.<br>س29: إذا ثبت اتباع العامل سلوكاً سيئاً ، أو ارتكابه عملاً مخلاً بالشرف أو الأمانة:.cيجوز فسخ العقد دون مكافأة.<br>س30: الهيئة الهندسية المقرة من مجلس الوزراء هي:.bالهيئة السعودية للمهندسين.<br>س31: أول مؤسسة جامعية في المملكة هي:.aكلية الشريعة بمكة المكرمة.<br>س32: عالج الإسلام العادات النفسية كالنميمة والغيبة بـ :.cالتوجيه المحيي للقلب.<br>س33: عدّ المؤلف صفات الصديق الصالح، وأولها:.aالعقل.<br>س34: يجب مراعاة عدم الإكثار منه في التربية:.cالثواب والعقاب.<br>س35: الأكل المباح عن جوع هو:.aاستجابة لغريزة جسدية.", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias201-ias-212/100780/4", "user": "user6441", "ts": 1295177796000, "tid": 100780, "pn": 4}}', 1295177796000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p766583-ias212', 'stk-everest', 'IAS 212', 'srcP', '{"html": "حاولت اضبطه على السريع<br><br>دعواتكم 🌹<br><br>​<span data-fid=\"stk-f766583-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f766583-0": {"name": "فاينل 93.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias201-ias-212/100780/22", "user": "EvErEst", "ts": 1295433730000, "tid": 100780, "pn": 22}}', 1295433730000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p864882-ias212', 'stk-equal', 'IAS 212', 'srcP', '{"html": "ias 212 … (attached)<br>ias 201 … http://skfupm.co/showpost.php?p=789846 + http://skfupm.co/showpost.php?p=789872<br>ias 111 … http://skfupm.co/showpost.php?p=742758 + http://skfupm.co/showpost.php?p=827830<br>ias 101 … http://skfupm.co/showpost.php?p=742755 + new docs are attached<br><br>ولا عاد أشوف بني آدمي يجي يطلب اولد اقزام 😆<br><br>​<span data-fid=\"stk-f864882-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>ias 101 old exams.zip (99.5 KB)", "files": {"stk-f864882-0": {"name": "ias 212 old exams.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/d6b48e3e143b42831973e691c47536281e51d92a1943471704abdff9018c848b"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias201-ias-212/100780/35", "user": "equal", "ts": 1310125755000, "tid": 100780, "pn": 35}}', 1310125755000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p964298-ias212', 'stk-me_i10', 'IAS 212', 'srcP', '{"html": "في المرفقات فاينل212 سمستر 103<br><br>​<span data-fid=\"stk-f964298-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f964298-0": {"name": "أسئلة الاختبار النهائي.docx", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/b1706d7ae7479c97ab88892c42f9bdecda79af3c6d45377b2c0093d9a30e3b80"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias201-ias-212/100780/51", "user": "ME_I10", "ts": 1326260973000, "tid": 100780, "pn": 51}}', 1326260973000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p725562-ias212', 'stk-user6801', 'IAS 212', 'srcP', '{"html": "شاهد المرفقات<br><br>لاتنسوني من دعائكم ,<br><br>واللي عنده غيرها ياليت يفزع لنا<br><br>​<span data-fid=\"stk-f725562-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f725562-0": {"name": "نموذج الاختبار.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/fc992585c6bda568253972de64764003e56eb5b518dbb36a8e96fe8a6cfe05e3"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-212/97134/5", "user": "user6801", "ts": 1287767815000, "tid": 97134, "pn": 5}}', 1287767815000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-student_nz-ias212', 'stk-student_nz', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-mashookhi", "n": "د. عبدالله المشوخي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سمستر 101 اسلامي 212\n\n-----------------\n\nالتحضير :\nيوميا ولا نسي يوم واحد\n\nطريقة الشرح :\n\nشرح سلايدات\n\nالكويزات :\nعنده 3كوزات اكثر من سهلة والعادة تكون اختيارات\nقبل المياجر و الفاينل راح تساعد في المذاكرة للفاينل\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\nالقريد النهائي:\nB+\nالصوت:\n\nممتاز\n\nإضافات :\n- يعطيك اب قريد اذا كان باقي لك درجة على القريد اللي بعده\n\n- راح يطلب بحث عشان تاخذ الدرجة الكاملة\n* لازم تكتب اسمك ورقمك والشعبة في الصفحة الاولى على اليمين او اليسار\n* لازم تذكر المراجع اللي اخذت منها كلامك\n* طريقة صياغتك للموضوع تكون كويسه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p778473-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68621/21", "user": "student_NZ", "ts": 1296332100000, "tid": 68621, "pn": 21}}]}', 1296332100000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6661-ias212', 'stk-user6661', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-mashookhi", "n": "د. عبدالله المشوخي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسلامي 212 في ترم 102\n\nالإيجابيات:\n\nبصراحـه كلاسه غالبا ما يكون غير ممل لأنه يربطلك المادة بالحياة بشكل حلو…\n\nوما عنده مشكله انك تناقشـه وتتجادل معه (في المادة) فقط!\n\nاما اذا بتشطح خارج المنهج فالله يكون بعونك…يا تكون اهل النقاش او انتبه لعمرك!!!\n\nالسلبيات:\n\nوالله مدري وش اقول!\n\nالتحضير صارم جدا وما ينسى ابدا ولا يتساهل…\n\nاول ما يوصل للكلاس يجلس ويحضر ويحاسب عالتأخير…\n\nاي غياب بدرجة وكل 3 تأخيرات بدرجة!!…وحتى لو تغيب بعذر فبيشطب عالغياب بالكشف ويعده على انه (تأخير)…\n\nوانسسسسسسى شي اسمه دف درجات او مسح غياب او حتى مسح كويز…\n\nويطلب من كل طالب بحث تلقيه للطلاب بآخر 10 او 5 دقايق بالمحاضرة وعليه 6 درجات…انسى انك تاخذ 6 من 6…\n\nانا وكل اللي اعرفهم اخذو ا 5 من 6!!\n\nعن نفسي اخذت فل مارك بالميجر الأول والثاني وفي الفاينل نقصت درجة وما عندي ولا غياب وطلعت من الكورس بـ (آي بلس) بالحفففففففففففه ولله الحمد!!\n\nطبعا المادة عن (الأخلاق) والدكتور بعض الأحيان تطلع منه ألفاظ!!\n\nلا تعليييق!!!!\n\nمثل (بالكوندرة)…(طز)…وانت ماشي…\n\nيعطي 3 كوزات بالسمستر قبل الميجرين والفاينل ووكلها (اختيارات) وسهلة ولكن اي خطأ يعني درجة كاملة تطير منك…وما اعطانا كويز تعويضي…!!!\n\nبإختصار اذا انت راعي تأخيرات وغياب وبزوطـة انحش وفر منه فرارك من الأسد…\n\nاما اذا انت منضبـط فوضعك بالسليم ولا تحاتي…\n\nبالتوفيق ❤️…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p854046-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68621/24", "user": "user6661", "ts": 1308172631000, "tid": 68621, "pn": 24}}]}', 1308172631000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10218-ias212', 'stk-user10218', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-mashookhi", "n": "د. عبدالله المشوخي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 T-143\n\nالتحضير :\n\nبعد خمس دقائق\n\nكل كلاس ، الغياب بدرجة\n\nيسمح بالميك اب كم مره بس او اذا عندك سبب\nو لازم تعطيه خبر قبل\nطريقة الشرح :\n\nمتنوع\n\nسلايدات ، سبوره ، يطلع طلاب ويسئلهم عن رأيهم في الموضوع\n\nيتكلم عن منهج الكتاب + خارج الكتاب (قصص من عنده)\n\nالكويزات :\n\n15 درجة للكويزات\n\nيخليكم تختارون\n\n5 كويزات او 3 كويزات\n\nالمياجر:\n\nكومن\n\n*أنا خذتها في الصيف وهو كان يدرس أغلب السكاشن\nفا هو الي حط الأسئلة\nالفاينلات :\n\nكومن\n\n*أنا خذتها في الصيف وهو كان يدرس أغلب السكاشن\nفا هو الي حط الأسئلة\nالقريد النهائي:\n\nB\nالصوت:\n\nواضح\nإضافات :\n\n* في بونص الا اذا بدر تصرف سيئ من احد الطلاب ويكون\n\nدرجة في الخمس درجات اي 84 ==> 85 ، 54==>55\n\nاو\nدرجتين في العشر درجات اي 88==> 90 ، 58==>60\n\n* الرجال يتكلم عن المثاليه وهو بعيد عنها\n\nتصدق شفته كم مره بعد نهاية السمستر وأسلم عليه بس ما يرد السلام 😞", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437961-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68621/57", "user": "user10218", "ts": 1451885294000, "tid": 68621, "pn": 57}}]}', 1451885294000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-v3254-ias212', 'stk-v3254', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-mashookhi", "n": "د. عبدالله المشوخي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ias212\nterm 151\n\nلتحضير : كل يوم بداية الكلاس\nطريقة الشرح : متنوع حسب المزاج\nالكويزات : متوسطه\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي…\nالصوت: واضح\nإضافات : كل شي محسوب عليك في هالماده اللي بتنزلها عنده … وحقك يجيب بالتمام … فيه بونص يسويه 3 درجات فقط اذا حضرت له محاضره هو بيتفق عليها\n. نص الكلاس ادعائات للمثاليه مع قليل من القضايا الفلسطينيه ما يضرش .\nماشاء الله عليه الطلاب دائم يخطئون وهو الصح .\nنصيحه اذا تبي قريد كويس وما تبي تمل وتنغث من الماده شف غيره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438123-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68621/58", "user": "V3254", "ts": 1452045331000, "tid": 68621, "pn": 58}}]}', 1452045331000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10578-ias212', 'stk-user10578', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-mashookhi", "n": "د. عبدالله المشوخي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسلامي 212\nالفصل: 153\n\nبتكلم عنه بصراحة تامة …\n\nنظرة عامة :\nالمدرس قديم و معروف و سمعته بين الطلاب ماهي جيدة\nحتى انه شكله يعرف هالشيء خاصة انه في اول كلاس لنا معه قال \" اسمع مني ولا تسمع عني \"\nلكن بعد سمستر كامل عرفت ليش سمعته كذا\n\nالتحضير :\nبداية الكلاس ، دقيتين تقريباً\nسمح بغياب واحد مجاني خلال الترم\nمعظم المدرسين يعطون درجة للطالب اللي ما غاب ولا مرة لكن هو لا\n\nالشرح :\nعادة سلايدات و احياناً من دونها\nبصراحة شرحه جيد و جميل وممكن هي الحسنة الوحيدة اللي عنده\n\nالكويزات :\n4 كويزات مقسمة بترتيب على السمستر\n2 قبل الميدتيرم و 2 بعده\n3 اختياري و 1 صح و خطأ\n16 درجة ( تغلط بسؤال تروح عليك من الكورس كامل )\n\nبصراااحة كويزاته متوسطة مائلة للصعوبة\nأصعب الاسئلة اللي ممكن تشوفها بالميد تيرم و الفاينل بتلاقيها بالكويزات\n\nالمياجر:\nبفصل 153 كان المسؤول عن المادة و شكله هو اللي وضع اسئلة الميجر و الفاينل\nاصلاً واضح أنه هو اللي وضعها من شدة صعوبة بعض الاسئلة التي شتان ما بينها وما بين الاولد اقزام\n\nالفاينلات :\n^^^^^\n\nالبحث :\n4 درجات\nعنده تقريباً 40 موضوع عام يمرر الورقة بين الطلاب و كل طالب يختار الموضوع اللي يبيه\nو بنهاية الترم كذا تقريباً يطلب من كل طالب يطلع و يقدم عن البحث لمدة دقيقتين\nمعظم الطلاب اخذوا 4 الا اللي تأخر او غاب عن التقديم …\n\nالقريد النهائي:\nقريدي اخذت A\nاما المدرس اعطيه C\n\nالصوت:\nواضح\n\nإضافات :\n- مدرس مزاجي ، عادة يكون متنرفز و يصارخ ، صحيح أن بعض الطلاب يرفعون الضغط لكنه بصراحة هي عصبية اللي تخلي الطلاب يرتبكون و هو من المفترض يكون اكثر صبر .\n\n- بونص يعطي درجتين فقط ، واحسه شوي و يقول كثيرة عليكم هههه ، لكن بصراحة معظم الطلاب ما يستفيدون منها كثير لانها بتروح عليها درجات الكويزات الرهيبة اللي راحت .\n\n- اتمنى إني ما ظلمته بهالتقييم لكن بصراحة زعلني على بعض الاسئلة الصعبة للغابة بالكويزات و الاختبارت .\nو جزاه الله خير\n\nالسؤال الذي يطرحه معظمكم ، هل اسجل عنده او لا ؟\nاذا فيه مدرس غيره تقدر تسجل عنده لا تسجل عند المشوخي ، واذا ما فيه الا هو يناسب جدولك ، سجل لكن لازم تنتبه و تسوي كل اللي يقولك عنه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1456194-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68621/64", "user": "user10578", "ts": 1472564634000, "tid": 68621, "pn": 64}}]}', 1472564634000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jstnawwaf-ias212', 'stk-jstnawwaf', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-mashookhi", "n": "د. عبدالله المشوخي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS212 T153\nالتحضير: من أول دقيقة، لا تتأخر ولا تغيب.\nالشرح: ممتاز جدا، يبدأ بخاطرة ثم أحيانا سلايدات وأحيانا بدون ويطلع طلاب ويسألهم أسئلة أخلاقية عميقة.\nالكوزات: نار، كل سؤال بدرجة من المجموع النهائي، كنت أقرأ الكتاب + أحل كل الأولدإكزام حق الدرس قبل الاختبار وطلعت فيها كلها فل الحمدلله.\nالميد: أول سؤالين بالميد جتنا بالنص من الكويزات، والميد يحتاج تركيز كبير، يعني انسى 111، في 212 تحتاج تستعد أكثر.\nالفاينلات: نفس مستوى الميد، مائل للصعوبة، يحتاج تركيز واستعداد كويس.\nالقريد النهائي: B+, اللي نقص التقييم عصبيته أحيانا اللي مالها داعي، وأيضا الحصة ممكن تكون أمتع وفيها نقاشات أكثر مع الطلاب.\nإضافات: الدكتور عادل جدا لذلك سمعته مو مثل الدكاترة اللي يدفون، بالرغم أنه عطانا درجتين بونص بشرط أننا نعطي هدية لأمهاتنا بعيد الأضحى “بعد كم يوم”، وأيضا اللي باقي له درجة على ال A+ يزوده.\nالكورس للأمانة أحمد ربي إني أخذته بالصيف لأنه ما يقارن ب 111، يحتاج تركيز ومذاكرة ممتازة، طلعت فيه ب A+ لكن بالترم العادي احتمال كبير يكون أقل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457220-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68621/68", "user": "jstNawwaf", "ts": 1473294819000, "tid": 68621, "pn": 68}}]}', 1473294819000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-everest-ias212', 'stk-everest', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-sendi", "n": "د. حسن سندي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ias212 term: 101\n\nالتحضير: يوميا ينادي بالاسم\n\nطريقة الشرح: يقرا من سلايدات هو مسويها، صراحة طريقة مُملة\n\nالكويزات: سبعة كويزرات كل واحد عليه 1% يكون سؤال واحد بسيط\n\nالمياجر: كومن\n\nالفاينلات: كومن\n\nالقريد النهائي: +B\n\nالصوت: مسموع بس على نبرة وحدة\n\nإضافات: في سبعة واجبات كل واجب سؤال واحد عليه 1% وتكون على الويب سي تي\nفي نهاية السميستر شال من كل واحد غياب و سوا كويز زيادة وكان سؤال انت الي تكتبه وتجي الكلاس وتجاوب عليه (يعني درجة مجانا)\n\nوقال لينا ان ادا باقي لك درجة على الجريد اللي بعده بعطيك ايها، وادا باقي لك درجتين بشوف ادا درجات الغيابات او الكويزات او الواجبات كاملة بيرفعك الى الجريد الي بعده\n\nالمدرس صراحة اخلاق ومتساعد مع الطلاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p779233-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-sendi/68622/25", "user": "EvErEst", "ts": 1296422312000, "tid": 68622, "pn": 25}}]}', 1296422312000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.cool-ias212', 'stk-mr.cool', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-sendi", "n": "د. حسن سندي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ias 212 - 102\n\nاستاذ خلووووق جدا جدا و محترم و ماشي على النظام بالملي\n\nالتحضير: كل يوم و لا يمشي إلا بعذر رسمي ، و لا يسمح بالتاخير فوق 5 إلى عشر دقايق .\n\nالشرح: سلايدات و لا يعترف بالكتاب ، لكن يكثر كلم على أشياء سهلة …\n\nالكويزز : أسهل كويزات مرت علي في الجامعة …\n\nإضافات: آخر اسبوع خلانا نقدم برسينتيشن عن آخر المنهج إلي يبغى يقدم يأخذ بونس …\nلا يسمح بمن يلبس ملابس قصيرة بالدخول للمحاضرة ، و حضرت تهزيئة لواحد من الطلاب على اللبس …\n\nمن أفضل من درست عنهم خلقا …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p921566-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-sendi/68622/27", "user": "Mr.Cool", "ts": 1318956303000, "tid": 68622, "pn": 27}}]}', 1318956303000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmad18-ias212', 'stk-ahmad18', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-sendi", "n": "د. حسن سندي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسلامي 212 - 111\nبنود التقييم :\n\nالتحضير :كل كلاس , بداية الكلاس , وترا ياشباب يحط ( متأخر ) وكل 3 تاخيرات بغياب , ف انتبه !\n\nطريقة الشرح : من السلايدات , واحيان يسال اسئلة , يحمس الطلاب .\n\nالكويزات : 7 كويزات . اسبوع ايه واسبوع لأ وكويزاته (موووووووووووووووووووووووووووووووووووووووووووووووووووووية ) بس اقرأ ( قراءة بتركيز ) اللي مطلوب في الكويز وبتاخذ العلامـة …\n\nالمياجر: كومون\n\nالفاينلات : كومون\n\nالقريد النهائي: A\n\nالصوت: واضح .\n\nإضافات :\n\n* البونص عنده بالكيلو , لا تفوتوه ياشبآب.\n\n* لا تنسى مراسمك واقلامك واوراقك , لانه يعصب اذا محد جابهم .\n\n* متفهم , واذا كان عندك مشكلة شخصية او شي يكون من اوائل الناس سماعا لك .\n\n* بصراحة : في بداية الترم حتحس من تعامله انه ( عصبي , متشدد , ما يحب يتكلم مع الطلاب! شايف نفسه يعني !) لكن اقسم بالله عنده قلب … تتعب وانت تقول طيب , يعاملك كأخ أصغر, حتكتشف شخصيته اذا اتعاملت معه بره الكلاس ( ويب سيتي , اوفس اورز ).\n\n* اسمع كلامه , واحفظ قواعده , بيمشي الكلاس معاك سلام سلام ,\n\nبالأخير : الله يحفظك يا دكتور حسن وين ما كنت 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p965205-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-sendi/68622/28", "user": "Ahmad18", "ts": 1326338629000, "tid": 68622, "pn": 28}}]}', 1326338629000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4492-ias212', 'stk-user4492', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-sendi", "n": "د. حسن سندي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "لو لم يوجد كتاب لمادة الاسلامي 212 لكان الدكتور سندي كتاباً بأخلاقه وشرحه وتفاهمه مع الطلاب 🌹\nكوزات شبه اسبوعيه وسؤال واحد بسييييط جدا.\nالبببببببببونص من هنا إلى بكرة.\nمرتب ومنظم جدا أثناء الشرح والتحضير.\n\nالله يوفقه وياليت دكاترة القسم يحذون حذوه ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1218723-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-sendi/68622/35", "user": "user4492", "ts": 1367655958000, "tid": 68622, "pn": 35}}]}', 1367655958000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8697-ias212', 'stk-user8697', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-sendi", "n": "د. حسن سندي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 Term122\n\nالتحضير :\n\nتضير يومي بعد ما يدخل الكلاس ويجهز الكمبيوتر\n\nطريقة الشرح :\n\nسلايدات يخلي الطلاب يقرؤوها كل كلاس طالب وله بطاقتين(بشرح هرجة البطايق بعدين)\nلو اعتمدت على شرحه في المياجر تجيب درجة حلوة فما بالك لو ذاكرت\n\nالكويزات :\n\nست كويزات واحد استبدله بحضور محاضرة مع اخذ ملاحظات منها أو عمل بحث\nالكويزات عادة تغطي جزئ طيب من المنهج ولو استعديت لها راح تمر على الكتاب مرور الكرام وقت الميجر\n\nالمياجر:\nالفاينلات :\n\nكومون\n\nالقريد النهائي:\n\nA+\n\nالصوت:\n\nجدا واضح\n\nإضافات :\n\n*البطائق: بدأ بنظام البطائق هذا الترم وهي حركة جديدة وحلوة.\nخلال شرح الدرس في بعض النقاط في السلايدز يسأل الطلاب عنها واللي يجاوب له بطاقة.\nالفائدة من البطايق هي انك اذا جمعت ثلاث بطائق تقدر تعوض درجة كويز او اذا جمعت 10 بطائق تآخذ آبقريد يعني لو درجتك على حافة ال A بتاخذ A+\n\n*البونص: الطالب اللي ما عنده غيابات كثيرة ودرجات كويزاتك كويسة له بونص 3 درجات\n\n*الدكتور أخلاقه عاااالية جدا وهو فعلا مثال عملي للمادة اللي يدرسها\n\n*طبعا يعطي خمس هومركات سهلة جدا كل واحد عليه درجة كاملة من الكورس فلا تفرط فيها ابدا\n* يستعمل البلاك بورد في التواصل مع الطلاب وهذي حركة حلوة تحسب له مقارنة ببقسة الدكاترة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1226028-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-sendi/68622/36", "user": "user8697", "ts": 1369227063000, "tid": 68622, "pn": 36}}]}', 1369227063000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8581-ias212', 'stk-user8581', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-sendi", "n": "د. حسن سندي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ias212 term 133\nالتحضير :\nيحضر مع بداية الكلاس وشديد في التحضير وفي نهاية الفصل غالبا يشيل غياب واحد واذ ماعندك غياب يعطيك درجة بونص واذا كان باقي لك درجة على القريد الي بعده يشوف درجاتك وحضورك ويزيدك اذا درجاتك ممتازة وماتغيب . اذا خلص الشرح يطلعك وغالبا قبل نهاية الكلاس\n\nطريقة الشرح :\nهو يطبق نظام المجموعات بحيث كل مجموعة لها عدد معين من الدروس كل عنصر فيها يشرح جزئية شعبتنا كان عددها قليل فما كان فيه الا مجموعة وحدة + فيه دروس خصوصا الي تكون في بداية السمستر يشرحها على السلايدات + بعد مايخلص كل عنصر في المجموعة يعلق ويشرح الجزئية بشكل مبسط . احيانا الكلاس يكون ممل بسبب المادة لكن مع الوقت راح يتغير الوضع والطلاب راح ياخذون ويعطون اكثر ويتناقشون مع الدكتور وهو نفس الشي .\n\nالكويزات\n: 5 كويزات & 5 واجبات تكون على البلاكبورد …والله يجزاه الف خير اذا خذت 3 من 5 في الواجبات او 3 من 5 في الكويزات تاخذ الدرجة كاملة والكويز سؤال واحد وخيارات.\n\nالمياجر: كومون\nالفاينلات :كومون\nالقريد النهائي: a+ واكثر\nالصوت:\nواضح لكنه شوي هادئ\nإضافات :\n- عنده شي اسمه بطاقة مشاركة وهي عبارة عن بطاقات كل 3 بطاقات عن درجة ( بونص ) واقصى عدد تاخذه 12 بطاقة يعني اقصى شي تاخذ 4 درجات\nوالبطاقة تاخذها اذا كنت خبير في المجموعة ( العنصر الي يشرح ) وكل عناصر المجموعة راح يكونوا خبراء وقادة .واذا بدعت في الشرح يعطيك بطاقتين زيادة والقائد في النهاية ياخذ 3 بطاقات على القيادة .\n- اذا كان عندك بطاقتين مشاركة يجبر الثالثة و يعطيك درجة .\n- في ارسال الواجبات والكويزات اكتب الرقم الجامعي + اسمك + الرقم التسلسلي والشعبة ولا راح تاخذ صفر حتى لو كان حلك صح.\n- الدكتور كل شغله على البلاك بورد .\n- في نهاية السمستر في دروس اسمها تطبيقات اخلاقية بحيث جزء معين ويخليك تشرحه طبعا على الباوبوينت والسلايدات يعطيك اياها يعني الي عليك بس انك تطلع وتقرأ واذا بدعت او جبت شي جديد يعطيك بطاقتين زيادة . اما المجموعات فشرح للجزئية مب على باوربوينت …جب معاك ورقة وخل فيها النقاط الرئيسة واشرح الجزئية كأنك تسولف مع شباب\n- شعبتنا كلها a+ وبقية الشعب اغلبها a+ والدرجات يرسلها على الايميل + تكون على موقعه\nhttp://faculty.kfupm.edu.sa/IAS/drsendi/\n- اشوفه ممتاز لكن الي ماله خلق مجموعات او كويزات او مضغوط يدور غيره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1390291-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-sendi/68622/45", "user": "user8581", "ts": 1408231552000, "tid": 68622, "pn": 45}}]}', 1408231552000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9534-ias212', 'stk-user9534', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-sendi", "n": "د. حسن سندي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ias212-133\nدكتور محترم بكل ماتعنيه الكلمة من معنى ❤️\nيقدس شيء اسمه غياب … اذا بتغيب لاتنزززززززززززززل عنده ولا تفكر 🤠\nعنده نظام مجموعات ويعطيكم بونص عليه (الوضع سهالات بستفيد بونص ومهارة الالقاء وتتكلم يعني قدام الناس )\nاختباراته سؤال واحد واختيارات وسهل ولا يحتاج تذاكر 😆\n\nالزبدة لاتغيب وسو اللي يبيه بتاخذ بونص فوق ال5 درجات بالراحة 😊\n\nوالكورس سهل جدا جدا ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1391514-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-sendi/68622/46", "user": "user9534", "ts": 1408580712000, "tid": 68622, "pn": 46}}]}', 1408580712000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sabfas-ias212', 'stk-sabfas', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-sendi", "n": "د. حسن سندي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ias212 - ترم 141\n\nالدكتور محترم ورسمي مع الطلاب … شديد جداً في الحضور والتأخير ( لو تتأخر 10 دقائق مثلاً ماراح يدخلك ) ويحضّر بشكل يومي.\nنظامه يوزّع الطلاب قروبات … تقريباً كل اسبوعين راح يكون على قروبك عرض لازم يقدمه قدام الكلاس ( برزنتيشن ).\n\nعنده بونص يصل الى 6 درجات ان ماخاب ظني … بس طبعاً بمقابل وماهي مجانية 😛\n\nتقييمي له : B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1427079-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-sendi/68622/47", "user": "sabfas", "ts": 1441275638000, "tid": 68622, "pn": 47}}]}', 1441275638000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cs_scientist-ias212', 'stk-cs_scientist', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-sendi", "n": "د. حسن سندي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ias212-152\n\nالتحضير :\nشديد بالتحضير، ما يحب التأخير\nإذا أنت تحضر متأخر، ما أنصحك تسجل عنده\n\nطريقة الشرح :\nشرحه حلو و المادة بسيطة أصلًأ\n\nالكويزات :\nعطانا خمس كويزات سهلة جدًا، كل كويز فقرة اختياري واحدة\nلو تقرأ الكتاب على السريع قبل لا تجي بتجاوب\nلو تجيب 3 كويزات صح من الـ5، راح تاخذ 5% كاملة حقت الكويزات\n\nالمياجر:\nكومون\n\nالفاينلات :\nكومون\n\nالقريد النهائي:\nA+\n\nالصوت:\nواضح\n\nإضافات :\nالهوموورك عنده نفس الكويزات، سؤال واحد تحله و ترسله له بالبلاك بورد\nإذا حليت 3 هومووركات من 5 بتاخذ 5% كاملة\nبس فيه شيء لازم تنتبهون له، في الهوموورك و الكويز يقولك اكتب رقم الشعبة و الرقم التسلسلي\nتراها نقطة مهمة، ما يقبل أي كويز أو هوموورك ما عليه الرقمين ذولي\nممكن تحسون إنه شديد و كذا، بس الدكتور حبيب و أخلاقه حلوة والله\nهو ما يحب الطالب المهمل، و ما ألومه صراحة، و تراه أبدًا مو مصعب المادة\nصحيح يسوي أشياء كثيرة، بس كلها سهلة و يتساهل معنا فيها\nالنقطة اللي أعجبتني جدًا في الدكتور إنه مرتب و منظم\nصفحته في البلاك بورد فيها كل شيء، السيلابس و سلايداته و الشعب و الأرقام التسلسلية و اختبارات قديمة، و يحط اشعارات و يرسل رسايل بشكل منظم و ينبهك عن الكلاسات الملغية، و يرفع درجات الميدتيرم أو الفاينل أول ما توصل له\nريحنا جدًا صراحة، لأن انغثيت من نظام بعض دكاترة هذا القسم، يخلص الترم و أنت ما شفت السيلابس\nو الدرجات يقولك تعال شوفها على مكتبي معلقة، و بعضهم يغيبون وولا يردون خبر\nأما الدكتور حسن الله يعطيه العافية كل شيء في البلاك بورد و الإيميل\nالدكتور يعطي 5% بونص، 1% إذا ما عندك ولا غياب، و يعذرك في غياب واحد بس يروح عليك البونص\n4% من البطاقات اللي تجمعها، إذا جمعت 12 بطاقة تاخذ 4% كاملة\nسهل تجميع البطاقات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1450325-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-sendi/68622/48", "user": "CS_Scientist", "ts": 1464144690000, "tid": 68622, "pn": 48}}]}', 1464144690000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-2ams-ias212', 'stk-2ams', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-sendi", "n": "د. حسن سندي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212\nTerm 203 (online)\n\nالدكتور حسن سندي مختلف تمامًا عن التقيم الموجود في المنتدى خلووووق جداً وحبيب ومتعاون لابعد درجة وشرحه واضح وبسيط.\n\nالشرح وطريقة التدريس:\nأول اسبوعين الدكتور عرف المادة وشرح الأساسيات بعدها قسم الدروس على الطلاب كل طالب يشرح ثلاث مرات إضافة الشرح كان في مجموعات وليس فردي وممكن تختلف المجموعة الي معك اختلاف بسيط من شرح لثاني. وكان الدكتور يطلب من الطلاب يكتبون أسئلة في المحادثة (تيمز) ويجاوب على الاسئلة بعد ما تخلص المجموعة من الشرح. واذا كان فيه تعليق على الشرح او الدرس علق.\n\nالبونص :\nالبونص كان عبارة عن ثلاث درجات\nكيف تأخذ هذي الدرجات ؟!\nتأخدها بكل بساطة انك تكتب اسئلة في المحادثة بعد نهاية الشرح وتكتب رقمك التسلسلي قبل السؤال والدكتور بيسجل لك الدرجة.\nكل سؤال عليه نص درجة.\n\nالاختبارات القصيرة (الكوزات) :\nالاختبارات القصيرة وزنها 10 درجات\nخذنا اربع اختبارات، وزن الاختبارات\nالاول: درجتين\nالثاني: ثلاث درجات\nالثالث: ثلاث درجات\nالرابع: درجتين\nطبعا الاختبارات سهلة وبسيطة وكل سؤال بدرجة.\n\nالواجبات:\nالاول :\nمحاضرة مقدمة من أكاديمية الفوزان المطلوب نحضر المحاضرة ونكتب تقرير عنها (نلخصها) في خمس صفحات (ورد) ونسلم التقرير مع شهادة الحضور.\nهذا الواجب عليه 6 درجات والاغلب إذا ما كان الكل خذ الدرجة كاملة.\n\nالثاني:\nالواجب الثاني عبارة عن مدونات مقسمة علي مجموعات كل مجموعة فيها تقريبا 8 طلاب والمطلوب من المجموعة تقسم مواضيع المدونة وتجهز عرض وتقدمه كل طالب بيقدم في اقل من ثلاث دقايق.\nهذا الواجب عليه 9 درجات.\n\nإضافات:\nالدكتور بشكل عام حريص على الطالب ومتعاون بشكل كبير ويرد على جميع الاستفسارات\nوسهل تاخذ عنده A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531713-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-sendi/68622/61", "user": "2ams", "ts": 1631005887000, "tid": 68622, "pn": 61}}]}', 1631005887000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chemist-ias212', 'stk-chemist', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-humaidan", "n": "د. عصام الحميدان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معه ias 212 ترم 093\n\nالتحضير :\nكل يوم اول 10 دقايق\n\nطريقة الشرح :\nممتازة ويوزعنا بعض الاحيان على شكل مجموعات ويناقش معنا موضوع معين\nالكويزات :\nسهله وتقريبا كل اسبوعين كوز وطريقة حلوه في الكويزات مايجي الميجر الا وانت حافظ المتيريل\n\nالمياجر:\nسهله عدا سؤال او سؤالين يكون فيها ترك (في093 المياجر والفاينال من عنده وليست كومون)\n\nالفاينال:\nجزاه الله خير نصف الاسئلة من ميجر ون وتو\n\nالصوت:\nواضح\n\nالقريد النهائي:\n+a\n\nنصيحة:\nاذا شفت اسمه نزل معاه دون تردد لاسباب\n1) الدكتور في قمة الاخلاق\n2) يعطي درجات زيادة (بونس) على بعض المناقشات في الويب سيتي\n3) حصته خفيفة (سواليف ومناقشات)\n4) اسئلة سهلة اذا ذاكرت صح\n\n*فيه عيب واحد بس انه بعض المرات يغيب ولايعطينا خبر وبعض الاحيان يتأخر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p733669-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/esam-al-humaidan/68628/39", "user": "Chemist", "ts": 1289140051000, "tid": 68628, "pn": 39}}]}', 1289140051000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dani21-ias212', 'stk-dani21', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-humaidan", "n": "د. عصام الحميدان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 111 … Ias 212\nالتحضير : بشكل يومي ودائما …\nطريقة الشرح : ممتازة وشيقة وأحيانا يستخدم الانترنت لاستعراض بعض المواقع والصور …\nالكويزات : 3 كويزات تقريبا وكل واحد عليه 3 … وسهله جدا جدا\nالمياجر: كومن وسهلة\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح\nإضافات :\nبالصراحة الدكتور روووعة + وكثير الغيابات + ويعطي انشطة بونس وعليها كلها تقريبا 6 درجات … يعني قريد كامل + الكلاس ما يكون ممل لان يسوي نقاشات وقروبات\nاذا ما تبغى اتحس ان عندك مادة نزلها عنده ولا بتندم ابدااا\n\n** لا تفوته قد ما تقدر **", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p973105-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/esam-al-humaidan/68628/56", "user": "DANI21", "ts": 1327407528000, "tid": 68628, "pn": 56}}]}', 1327407528000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_old-ias212', 'stk-the_old', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-humaidan", "n": "د. عصام الحميدان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده (صيف 113) مادة (إسلامي 212)\n\nالتحضير : شديد جداً و يحضر باللابتوب حقه.\n\nطريقة الشرح : سواليف, لكن المادة ما تحتاج شرح.\n\nالكويزات : أعطانا كويز واحد بس كان سهل مرة. يعني لو منتبه معه في الشرح تجيب فل.\n\nالقريد النهائي: a+\n\nالصوت: واطي بعض الشيء.\n\nإضافات : الأستاذ يستخدم الويب سيتي في تواصله مع الطلاب. ينزل الدرجات ( المياجر, الكويزات, النشاط …إلخ) على طول و بدون تأخير. غاب علينا مرتين بدون ما يعلمنا. يحضّر دائماً بعد مرور خمس دقائق من الحصة. ما يقبل إنه أحد يحضر في غير سكشنه أبداً.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1078827-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/esam-al-humaidan/68628/60", "user": "the_old", "ts": 1344802366000, "tid": 68628, "pn": 60}}]}', 1344802366000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-old_oria-ias212', 'stk-old_oria', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-humaidan", "n": "د. عصام الحميدان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا درست عنده اسلامي 212 ترم 113 الصيف\nالدكتور ماعاد عنده شي اسمه بونص ما ادري ليش تغير نظامه\nيعني الدكتور تحول من افضل دكتور الى اسوأ دكتور عشان البونص اللي الغاه\nوالكلاس وورك عنده عبارة عن كويزات وانشطة تقرأ كتاب حدود 50 صفحة بعدين يسالك عليه كانه ميجر\nيعني قريد بيروح عشان الكلاس وورك حقه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1078856-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/esam-al-humaidan/68628/61", "user": "old_oria", "ts": 1344814070000, "tid": 68628, "pn": 61}}]}', 1344814070000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-brain_man-ias212', 'stk-brain_man', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-humaidan", "n": "د. عصام الحميدان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "دكتور جيد في الدرجات والبونس ،،\n\nالشرح عادي جداً ،، وغالبا ما يجيب النوم\nويغيب عادة 3 أو 4 مرات في السمستر ،، يكون فيه مؤتمرات\n\nانصح به في ias 212", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1104370-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/esam-al-humaidan/68628/64", "user": "Brain_Man", "ts": 1349615040000, "tid": 68628, "pn": 64}}]}', 1349615040000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman.h-ias212', 'stk-abdulrahman.h', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-humaidan", "n": "د. عصام الحميدان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 - term 111\n\nأسوأ كورس إسلامي أو عربي مر علي … كريه وثقيل . تحسفت اني ما سمعت كلام من جربه وحذف الكورس من عنده .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1123245-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/esam-al-humaidan/68628/66", "user": "Abdulrahman.H", "ts": 1353789318000, "tid": 68628, "pn": 66}}]}', 1353789318000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10207-ias212', 'stk-user10207', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-humaidan", "n": "د. عصام الحميدان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 - Term 142\n\nالتحضير : يحضر بداية الكلاس.\nطريقة الشرح : سوالف ويستخدم الإنترنت ويدخل مواقع ويبحث وكذا في الشرح.\nالكويزات : كويزين سهلين جداً عليهم 6 درجات. (3 منهم بونص). الكل فل مارك.\nالمياجر: كومن.\nالفاينلات : كومن.\nالصوت: واضح.\nإضافات :\n- شديد جداً في التحضير.\n- إذا كنت بتغيب لازم تقوله أو ترسله ايميل. بعدها تحضر مع سكشن ثاني. ويخصم نصف درجة.\n- في الكلاس، يحب شغل القروبات. كل كلاس تقريباً تتناقش مع الي جنبك.\n- فيه قروب بروجكت بسيط آخر الترم. وعليه بريسنتيشن. الكل فارك مارك.\n- فيه عنده هومورك عليه 3 درجات بونص، تلخيص فيديو من اليوتيوب وتكتبه وتسلمه له في صفحه وحدة.\n- وبكذا يكون عنده مجموع البونص 6 درجات.\n- الكلاس بعض الأحيان طفش، لكن الدكتور محترم جدا واخلاق.\n- يستخدم البلاكبورد والايميل ويرد بسرعة. ايضا يرسل درجات الميجر والفاينل والسلوشن ومجموع غياباتك.\n- آخر كلاس في السمستر اذا حضرته يلغي عليك غياب واحد.\n- ترم 142 الظاهر كان آخر ترم له بالجامعة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1422824-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/esam-al-humaidan/68628/80", "user": "user10207", "ts": 1437477261000, "tid": 68628, "pn": 80}}]}', 1437477261000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10282-ias212', 'stk-user10282', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-humaidan", "n": "د. عصام الحميدان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\n\nنزلت معه IAS 212 - Term 161\n\n- الدكتور طيّب وبشوش\n- كلاسه مملّ\n- يحضّر بانتظام (إلا بعض الأيام لا يحضر فيها ، ما يكون له مزاج :D)\n- الكويزات كانت سهلة\n- الواجبات في النصف الأول من الترم كانت مشاركات في صفحة في الفيسبوك للمادة في النصف الثاني كانت أسئلة نجيب عنها في حدود نصف صفحة ونرسل الإجابات على الإيميل أو البلاك بورد.\n- البونس كان ثلاث درجات: حضور أي محاضرة (بشرط يكون لها إعلان) وكتابة ملخص عنها …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466674-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/esam-al-humaidan/68628/81", "user": "user10282", "ts": 1484960260000, "tid": 68628, "pn": 81}}]}', 1484960260000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-neran-ias212', 'stk-neran', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-humaidan", "n": "د. عصام الحميدان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 173 IAS 212\n\nالتحضير :بداية الكلاس يكون فيه واحد من الشباب يحضّرك اول ماتدخل الكلاس\nطريقة الشرح :نص الكلاس يكون برزنتيشن من الطلاب والنص الثاني يعقّب على كلام الطلاب وعلى هالحال من بداية الترم الى نهايته\nالكويزات :--\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:B+\nالصوت:صوته جدا واطي والدكتور يجيب النوم\nإضافات :بداية الترم يقسّم الكلاس الى اربع مجموعات وكل مجموعه تكون مسؤوله عن عمل يقدم في اخر الترم مثل العمل التطوعي وعمل استبيانات …\nالكلاس ورك كان عباره عن 10 برزنتيشن و 15 العمل اخر الترم طلب بحث عشان البونص اللي هو 3 درجات\nالكلاس جدا ممل تدخل تنتظر بس متى تطلع وما اعتقد راح تستفيد اي شئ", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1501620-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/esam-al-humaidan/68628/83", "user": "neran", "ts": 1540914479000, "tid": 68628, "pn": 83}}]}', 1540914479000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-ias212', 'stk-khdsa2022', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-humaidan", "n": "د. عصام الحميدان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : عصام الحميدان\nالمادة: IAS 212\nBY WHATSAPP\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير :\nيعين طالب مسؤول عن التحضير طول الترم في هي حظك نصيبك\nطريقة الشرح :\nسوالف إلى نهاية الكلاس\nالكويزات : لا يوجد\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A\nإضافات :\nالدكتور راح يطلب منك ثلاثة اشياء طول الترم\n١- تقديم فردي\n٢- خدمة مجتمع\n٣- مشروع يشترك فيه السكشن كامل\nوبمجرد إنجاز الشيء راح يعطيك العلامة الكاملة\nوأيضا الدكتور عنده ٣ بونص على تقرير لمحاضرة تحضرها في الليل\nسلبيات الدكتور هو أنه يخصم مباشرة على الغياب ف الي يغيب كثير ما انصحه بالدكتور ابداً.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518820-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/esam-al-humaidan/68628/84", "user": "Khdsa2022", "ts": 1578292947000, "tid": 68628, "pn": 84}}, {"id": "stk-dr-muzeini", "n": "د. خالد المزيني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATSAPP\nاسم الدكتور : خالد المزيني\nالمادة: IAS 212\nالفصل الدراسي:191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : بداية الكلاس او نهايتة ويسجل لييت\nطريقة الشرح : يحب يسولف عن تجاربه الشخصية الكثييرة والكلاس حلو معاه\nالكويزات : نادرة وفجأة\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي: B\nالصوت: متوسط\nإضافات : الدكتور كنت اسمع ذم عنه وانه مايعطي بونص بس تفاجئت في النهاية عطانا اغلبنا في كويز فل و شال غيابين من كل شخص وليتين من كل شخص", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518833-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-muzeini/68633/30", "user": "Khdsa2022", "ts": 1578294204000, "tid": 68633, "pn": 30}}]}', 1578292947000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12007-ias212', 'stk-user12007', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-humaidan", "n": "د. عصام الحميدان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 Term 212\nالدكتور عنده منسقين ولهم 5 درجات بونص خاصة فيهم (ما اعرف الية اختيار المنسق) باقي الطلاب 3 بس ويسوي ابقريد اذا بقالك درجة\nيعني اذا جبت 89 تاخذ A\nللأمانة ما انصح فيه ابد خصوصا ان في دكاترة يوزعون بونصات بالهبل في طلاب زادوا قريد ونص لان دكاترتهم متفهمين\nافرجنا فاينلنا كان 25 من 35 (المادة تغيرت فالاولدات ما تفيد) مع ذلك ما عطانا بونص بالرغم من الافرج المنخفض\nما يسمح بالجوال نهائيا\nالحصة اغلبها سواليف لكن للامانة مفيدة بشكل عام لك\nفي النهاية لو انت منسق بتستانس مع الدكتور لان لك 8 درجات اضافية\nانصحك تدور دكتور متساهل اكثر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534374-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/esam-al-humaidan/68628/86", "user": "user12007", "ts": 1653217499000, "tid": 68628, "pn": 86}}]}', 1653217499000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-220v-ias212', 'stk-220v', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-muzeini", "n": "د. خالد المزيني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 - 172\n\nالتحضير : أول ثلاث دقايق من المحاضرة، واللي يجي بعدها يحضره نهاية المحاضرة. وكان يسمح بغيابين بدون خصم.\nطريقة الشرح : يشرح من سلايدات ويعقب على بعض النقاط المهمة. فيه طلاب في الشعبة يشوفون أنه طريقة الشرح مملة، بالنسبة لي مقبولة إلى جيدة.\nالكويزات : اختبرنا كويزين، الأول كان معطينا نص مكتوب واستخرج منه تعريف وفوائد… الكويز الثاني كان 3 أسئلة اختياري بسيطة. بالإضافة أنه يقسمنا مجموعات ويخلينا نسوي بعض الأنشطة الصَفية ويحسابنا عليها ( تقريبًا الكل ياخذ عليها كامل إذا طبقت المطلوب ).\nالفاينلات : كومن.\nالقريد النهائي: أعطيه C.\nالصوت: منخفض نوعًا ما لكن واضح.\nإضافات : الدكتور تعامله كويس، لكن عنده مشكلة في موضوع الدرجات، حقك راح تاخذه بدون بونصات ولا شي، أنت واجتهادك، ممكن في حالة وحدة لو غياباتك 2 أو أقل وتحتاج اب قريد ممكن تاخذ. وأيضًا عنده مشكلة في تأخير الدرجات، مثلاً الميد ترم اختبرنا وفيه طلاب من شعب أخرى استلموا النتائج بعدها بيوم، أما أحنا ظلينا أسبوع مع أنه كذا مرة نكلمه عنها، وأيضًا في القريد النهائي عطانا إياهم متأخر. وأيضًا ألغى تقريبًا 5 محاضرات بسبب ارتباطه بمؤتمرات وأشياء أخرى خارج الجامعة. الدكتور زي ما ذكرت فوق من ناحية الدرجات سيء، لو كنت بتشد حيلك وبتفهم الكتاب صح إن شاء الله تقدر تطلع بقريد ممتاز، ولكن لا أنصح فيه نهائيًَا كخيار أول إلا لو أنت مضطر.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492542-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-muzeini/68633/27", "user": "220V", "ts": 1526508685000, "tid": 68633, "pn": 27}}]}', 1526508685000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11942-ias212', 'stk-user11942', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-muzeini", "n": "د. خالد المزيني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(IAS212-Term 201 (Online\n\nفعل الطرق السحابية في حل الواجبات وتقديم المشاركات مثل Google drive. كان موجود معنا في قروب الواتساب ويتفاعل مع الطلاب.\n\nطريقة الشرح:\n\nيعرض سلايدات ويبدأ يتكلم ويشرح. سلايداته ليست مصدر للمذاكرة. وكذلك يعرض صور ويبدأ يناقشها ويطلب من الطلاب التعليق عليها مثل صورة لتمثال سيدة العدالة في الميثولوجيا الرومانية وغيرها وصور كاريكتورية. يجيب أشياء من تجاربه السابقة. ويحب الاستطراد؛ مثلاً في أحد الكلاسات تحدث عن الهندسة الاقليدية.\n\nطلباته:-\n\nبالنسبة لي اخترت الدكتور لأني سمعت عنه بأنه قليل الطلبات ويبدو بأنه كذلك لكن مع الأونلاين كانت طلباته كثيرة لكن مقارنة بغيره أشوف إنها مقبولة:-\n\n١- طلب منا ( Presention ) وكان عبارة عن اختيار موضوع من مواضيع الثورة الصناعية الرابعة وربطها بموضوع الأخلاق.\n\n٢- وطلب أيضاً تلخيص. أرسل كتب وتختار واحد منها وتلخص فصول منه مع مجموعتك بعدين تجمعونها في ملف واحد وتكتبون مقدمة وخاتمة. وفي ترمنا كانت الكتب عن موضوع إدارة الغضب\n\n٣- طلب منا حضور ندوتين، وحدة منهم كجزء من النشاط والثانية عليها بونص درجتين. طبعاً لازم تقدم تلخيص في عشر نقاط.\n\n٤- قسمنا لمجموعات وكان عملنا لمدة أسبوعين تقريبا عبارة عن قراءة لنظام العمل السعودي كامل ( 245 مادة ) واستخراج نقاط محددة وكان بروجكت ممتع ومفيد.\n\n٥- طلب منا أيضاً تقديم حالة دراسية ( Case study ) على فقرات من ميثاق المهندس.\n\n٦-تقديم بروجكت عن تسوير الكلام وكان مع مجموعات. تأتي بجمل وعبارات مهملة ثم تسورها وهكذا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527244-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-muzeini/68633/32", "user": "user11942", "ts": 1608822281000, "tid": 68633, "pn": 32}}]}', 1608822281000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-ias212', 'stk-guest', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khushaim", "n": "د. فهد الخشيم الدوسري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسلامي 212\n\nالتحضير : أول الكلاس ينادي على الاسماء\nطريقة الشرح : يفتح المجال بشكل كبير للنقاش و يسمع من الجميع وهذا اللي كان يخلي الكلاس ممتع جدا ومفيد أيضا\nالكويزات : ما في\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: a+\nالصوت: واضح\nإضافات : فعلا من أفضل الدكاترة اللي تعاملت معاهم في الجامعة ، واللي يدرس عنده بيكسب أخ قبل ما يكسب أستاذ", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1282144-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fahad-alkhushaim-al-dosssary/148173/3", "user": "Guest", "ts": 1383510268000, "tid": 148173, "pn": 3}}, {"id": "stk-dr-khaldi", "n": "د. عبدالرحمن الخالدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS212 ترم الاون لاين 201\n\nالتحضير : يحضر بالاكسل بداية الكلاس … اذا تاخرت اكثر من عشر دقائق يسجلك غياب … لكنه يتسامح معهم في اغلب الحالات\nطريقة الشرح : يقسم المنهج على مجموعات وكل يوم مجموعه تشرحه عن طريق مايكروسوفت تيم\nالمياجر: مستواهم نفس اغلب الاترام لكن كثروا من اسئله الكيسس “اعطى محمد موظف البلدية جوالًا لاعتقاده بان هذا العمل يسرع من اجراءات مخالصته” فعل محمد يعتبر هدية او رشوة ^ مثال لما اقصد … وكرأي شخصي اشوف هالاسئلة اسهل … وكل سؤال دقيقه … كافي جدًا للي مذاكر\nالفاينلات : نفس المياجر ما عدا انهم سمحوا بالباك تراكينق في الاسئلة\nالقريد النهائي: A+\nإضافات : دكتور محترم جدًا وقدّر اوضاع الاون لاين الصعبه عندنا الله يجزاه خير … الكرف مو كثير ابدًا … شرح الوحده وهو مجهز سلايدات وعادي تستخدمهم يعني شغله تحضير ربع ساعه وانتهينا … وعنده تلخيص كتاب ساعه وانت مخلصه … واستبيان بسيط شغل عشر دقايق … تقدر تحصل في اعمال السنه 48 من 40 … الباقي بونص", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527491-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-khaldi/148174/32", "user": "Guest", "ts": 1609594668000, "tid": 148174, "pn": 32}}, {"id": "stk-dr-muzeini", "n": "د. خالد المزيني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 Term 201\nباختصار قبل ما ابدا لا تنزلوا عنده أبداً حتى لو انحديت عليه نزلك عربي او جي اس\nاولا التواصل معاه صعب جدا مسوي قروب واتس معانا ولا يرد عليه، الواجبات غير واضحة طلباته، اجبرنا نحضر محاضرة ندوة وطلب تلخيص لها وعليها درجتين في خارج وقت الكلاس، وايضا طلب تلخيص ندوة اخرى وقال انها عليها بونص درجتين وفي الاخير ؟ اعتبرها جزء من الكلاس وورك كانه الندوة الاولى اللي كان عليها درجتين ، لكن صراحة الميزة ان الواجبات مو مرة كثيرة.\nالمشكلة بعد ما تسوي كل الواجبات ومنت غايب ولا غياب ممكن تلقى نفسك ناقص ٣ او ٤ درجات كلاس وورك بس في ناس فللوا يعني عشوائية في التوزيع.\nوالدكتور مستحيل يدي بونص ، حتى في اسئلة في الميجر الاول بعض الدكاترة الثانيين حذفوها واعطوا درجتها لطلابهم اما دكتورنا ما سواها ، حتى ابغريد ما يعطي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527596-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-muzeini/68633/33", "user": "Guest", "ts": 1609822264000, "tid": 68633, "pn": 33}}]}', 1383510268000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ria-ias212', 'stk-ria', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-muzeini", "n": "د. خالد المزيني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212- Term 211\n\nالتحضير : يحضر اول ما يخش ببداية الكلاس (يتاخر دائما 2-5 دقائق) وما يحسبك تأخير من يوم ما يفتح اللابتوب\nطريقة الشرح :يسولف عن اشياء بره المنهج ويجيب كتب مالهم دخل بالمنهج ولا شيء ويسولف عنهم طول الكلاس من دون ما يشرح شيء من المنهج بعدين شاف انه الطلاب متاخرين بالمنهج سوه نظام مجموعات وكل يوم اثنين من الطلاب يقدمون الدرس.\n\nالكويزات : ما عطانا الا كويز واحد وكان اختبار تجهيز للميد عليه 5% من 100%\n\nالمياجر: ميد (كومن)\n\nالفاينلات : (كومن)\n\nالقريد النهائي: F+ وبجداره بعد\nالصوت: جيب معك مخدة عشان تنام\n\nإضافات :الدكتور اسواء ما يكون حرفيا اسواء دكتور درست عنده اسلامي عذبني بالواجب, كان فيه واجب تلخص قال “الواجب بيسكر الساعة 4” الواجب سكر الساعة 12 واظطريت الحقها من الاسبوع الثاني الى 6 عشان اكلمه يفتح الواجب وكل مره كان يقول “اوه فتحته انا بس انت اللي ما شيكت” وهو لا فتحته ولا شيء ولا كان في طريقة اتواصل معه لانه لا يرد علي الاميل ولا بحوله اصلا, للامانه الدكتور مهمل حتى بالدرجات السكاشن كلها نزلت درجاته بعد الاختبار بيوم لا هو هذا اليوم الخامس وما نزل شيء, ما ابغى اظلم الدكتور لكن سيئ مره عدا شيء واحد فيه زين اللي هو الغياب يعطيك غيابين مجانا تغيبهم بعدها يخصم عليك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1532487-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-muzeini/68633/34", "user": "RIA", "ts": 1635053874000, "tid": 68633, "pn": 34}}]}', 1635053874000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-doi-ias212', 'stk-doi', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-muzeini", "n": "د. خالد المزيني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS212 - Term 211:\n\nالتحضير:\nكان ياخذ التحضير بالاسماء مباشرة بعد دخوله للكلاس بالاسماء.\n\nطريقة الشرح:\nيشرح الدرس من بوربوينت مجهزه وكان مرتب.\n\nالـQuizes:\nاختبرنا كويز واحد ولا عطانا درجاته.\n\nالـMidterm:\nكومن وكان سهل\n\nالـFinal:\nكومن , لكن كان صعب وفيه تريكات كثيره مره\n\nالقريد النهائي:\nB\n\nإضافات:\nالدكتور خالد من خيرة الدكاتره بالجامعه بس الطلاب ماينزلون عنده لان نادر جداً جداً يعطي بونص وصعب التواصل معه … طلب مننا تلخيص محاضرات سابقه بورقه وحده فقط.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535691-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-muzeini/68633/36", "user": "DOI", "ts": 1666894994000, "tid": 68633, "pn": 36}}]}', 1666894994000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah-o-ias212', 'stk-abdullah-o', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-suliman", "n": "أ. خالد آل سليمان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "KHALID AL-SULIMAN\nIAS212- term221\n\nالشرح: الدكتور مقسم الماده تقسيمه حلوه، مافيها كوزات، ويسأل بدايه كل كلاس عن اشياء الي خذناهم قبل والي يجاوب له درجه ولازم تجمع ٥ درجات طول الترم،وفي غيرها، الشرح من المذكره يشرح المهم ويذكر امثله وسوالف، شرحه واضح\n\nالتحضر: بعد بدايه الكلاس ب١٠د تقريبا، يدقق بالتتحضير اشوي\n\nالتعامل: متعاون وطيب\n\nمن ناحيه البونص عطا بونص، وكان على اسئله تجاوبهم بالكلاس\n\nالتقييم: A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536169-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-suliman/68637/71", "user": "Abdullah-o", "ts": 1673710756000, "tid": 68637, "pn": 71}}]}', 1673710756000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mb-lazm-ias212', 'stk-mb-lazm', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-suliman", "n": "أ. خالد آل سليمان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم ورحمة الله وبركاته\n\nانا جونيور خذيت معه ias212 اخرت الكورس على اساس انزله بسمستر ثقيل وفعلا هذا الي صار نزلت بسمستر مواد تخصص وثقيل للامانه هو رجال والنعم فيه لكن انا جاي اعطي الزبده شرحه ممل ولا هو ذاك الزود اخوياي الي كانوا منزلين معي عند دكاتره ثانيين كانوا فالينها ومستانسين حن كلاسنا كان ممل\nالدكتور مايحشم انت جاي من مبنى بعيد ولا لا توزيع الدرجات عنده سيء عقدنا اخوياي الي كانوا عند الحربي فلل لهم الكلاس وورك حنا ذل ام امنا يطلب اشياء واجده وواجبات وحوسه وسو لي ملخص واحضر لي الندوه الفلانيه وسو الدوره الفلانيه ولخص الشي الفلاني انا الفاينل جبت فيه ٢٢/٢٥ والميد ٢٣/٢٥\nانصدم بالاخير ان مجموعي ٧٧ خصم على ام امنا بكل شي مستحيل يعطيك شي بالسهل السمستر كان ثقيل والحمد لله جبت قريدات حلوه مواد التخصص الصعبه ياخوان طلعت فيها A وعندها اطلع بC+ اقسم بالله دمرنا هذا غير البرزنتيشن والمدري وشو والقرف والملل والاخلاق لك عليها الي منزلين عند الدكاتره الباقيين كانت امورهم تمام الا طلابه ماغير يشكون يعني ياخي ماده تو كريدت ليه معقد امها وبعدين يجيك يقول الجامعه طالبه نصعب الكورس ياخي صعب الاختبارات لا تدمرني على طول السمستر بماده تو كريدت وتقروش حياتي باقي الدكاتره وراهم مفللين لطلابهم ولا الجامعه طلبت منك انت بس والله العظيم سقطه بتاريخي نزلت عنده قلت عشان المبنى قريب تف على المبنى اذا السالفه كذا والله ياخوان اني ماجز لكن منغبن قبل ارقد قلت والله ل اكتب انا مب نريد زعلان على القريد طز انا زعلان على الغثى الي اضطريت اتحمله على تو كريدت الخص لك بودكاست ليه يعني بترك اولوياتي والخص بودكاست ولا احضر ندوه ولا يخلي عليها ٤ درجات ياخي ارحمني انا شلون توتلي ٧٧ فهمني والله العظيم لو تنزل معه بعد ماقريت كلامي ذا ف انا م ادري شقول هو عندي كلام بس والله الواحد ماوده يخطي تمنياتي لكم بالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1539743-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-suliman/68637/72", "user": "Mb-lazm", "ts": 1749098843466, "tid": 68637, "pn": 72}}]}', 1749098843466, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5216-ias212', 'stk-user5216', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-afzal", "n": "د. حافظ أفضل", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الترم 102 … اسلامي 212\n\nالتحضير : ورقة تمر على الطلاب وكل طالب يسجل اسمه لكن في نص الترم بدا يحضر بالصوت لانه اكتشف ان بعض الطلاب يحضرون بعض … يخلي الطلاب المتاخرين يسجلون اسمائهم بورقة خارجيه بغرض التخويف ولا يحاسب على التاخير\n\nطريقة الشرح : يشرح بلغة عربية سليمة ويشرح باستخدام السبورة احيانا … موسوعة لغوية ما شاء الله عليه يتكلم عربي و انجليزي و فارسي و باكستاني … ولكنته العربية والانجليزية جدا ممتازة , لا ينفك عن الدعاء للطلاب , بارك الله فيه , ونعم الاستاذ والله\n\nالكويزات : كوز واحد صح وخطا , سهل\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A+\n\nالصوت: واضح ومسموع\n\nإضافات : نزل عنده وانت مغمض … مايكرف وعندة بونص و اخر الترم يشيل بعض الغيابات عن كل الطلاب\nتضمن عنده الـ a+ اذا ضبطت عمرك في المياجر والفاينلات … عطانا كوز واحد و هوموركين ( كلهم سهالات )\n\nالله يجزاه خير ويبارك فيه … مسهل على الطلاب الله يسهل له امورة دنيا واخرة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p856015-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/afzal-hafiz/68639/34", "user": "user5216", "ts": 1308567146000, "tid": 68639, "pn": 34}}]}', 1308567146000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cesar_peace-ias212', 'stk-cesar_peace', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-afzal", "n": "د. حافظ أفضل", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": ".\n\nاسلامي 212 , ترم 113 + اسلامي 111 , ترم 093\n\nالتحضير : ورقة وإن لم يسعفه الوقت نادى بالأسماء\n\nطريقة الشرح : روتينيه ويسهب كثيرا في ذكر بعض الأمثلة والأدلة من خارج الكتاب + متجاوب مع الأسئلة بشكل كبير جدا\n\nالكويزات : لايوجد\n\nالمياجر: كومون\n\nالفاينلات : كومون\n\nالقريد النهائي: +a\n\nالصوت: واضح ويتكلم بلغة مفهومة للمستمع\n\nإضافات : يسمح بالحضور مع الشعب الأخرى + متساهل مع المتأخرين\n\n🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1079735-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/afzal-hafiz/68639/52", "user": "CeSaR_PeaCe", "ts": 1345098508000, "tid": 68639, "pn": 52}}]}', 1345098508000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulla_yahia-ias212', 'stk-abdulla_yahia', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-yzahrani", "n": "أ. يحيى الزهراني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أ. يحيى الزهراني ]\n\nIAS 212 - Term 132\n- التحضير : دائماً - ينادي الرقم التسلسلي + تقدر تحضر في سكاشن ثانية ,\n\n- طريقة الشرح : يشرح على السلايدات ، شرحه ممتاز يوضح المادة من جميع النواحي ,\n\n- الكويزات : ___\n\n- المياجر : كومن ,\n\n- الفاينلات : كومن ,\n\n- القريد النهائي : A\n\n- الصوت : واضح ,\n\n- إضافات :الدركتور محترم و عملي يكرف صراحة ( بعطي 5 بريزنتيشن لكل مجموعة أو 3 بريزنتيشن + تقرير ) + يعطي بونسات على الحضور الكامل 1% ، و المشاركات الصفية 2% ، و البريزنتيشن ,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1374995-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yahya-al-zahrani/148170/5", "user": "Abdulla_Yahia", "ts": 1401549912000, "tid": 148170, "pn": 5}}]}', 1401549912000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-voldy-ias212', 'stk-voldy', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-yzahrani", "n": "أ. يحيى الزهراني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 - Term 132\n\n- التحضير : دائماً - ينادي الرقم التسلسلي في نهاية الحصة و تقدر تحضر في سكاشن ثانية\n\n- طريقة الشرح : يشرح على السلايدات ملتزم بتسلسل الكتاب لكن يخرج عن سياق الكتاب ويتكلم في اشياء اوسع ويحب يتناقش مع الطلاب\n\n- الكويزات :ما فيه\n\n- المياجر : كومن\n\n- الفاينلات : كومن\n\n- القريد النهائي : +A\n\n- الصوت : واضح\n\n- إضافات :الدركتور محترم و أخلاق عالية جدا وزي ما قلت يحب يتناقش\n\nعيب الدكتور:\n1) وهذا يمكن ما يعتبر عيب لكن شيء ما يعجبني بالمدرس، انه بداية كل كلاس يسوي مراجعة للحصة الي قبل واذا جاوبت تاخذ درجة مشاركة\n2) أوراق العمل حقته قروشة، بما انه ما عنده كويزات. هي موب صعبة ولكن مشكلتها يبغالها وقت", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1375251-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yahya-al-zahrani/148170/6", "user": "Voldy", "ts": 1401615867000, "tid": 148170, "pn": 6}}]}', 1401615867000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulaziz999-ias212', 'stk-abdulaziz999', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-yzahrani", "n": "أ. يحيى الزهراني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "162-ias212\n\nالتحضير :\nمن مبدئ الأمانة … الدكتور يحضر عن الكلاسات الماضية و يسأل الطلاب كم عندك غياب 🙂\n\nطريقة الشرح :\nيراجع الحصة الماضية و يشرح من السلايدات وماشي بالسيلابس …\n\nالكويزات :\nم عنده …\n\nالمياجر:\nكومن …\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA+\n\nالصوت:\nواضح جدا …\n\nإضافات :\n- الدكتور صراحة اعتبره افضل خيار بعد الدكتور الخالدي بسبب انه الخالدي يعطي بونصات اكثر …\n- الدكتور عنده بريزنتيشن لحالك تسويه و فيه عمل جماعي ومنها تاخذ البونصات و قد تصل الى ٥ ددرجات …\n- الدكتور اخلاق و يحب مشاركة الطلاب و فاهم المادة .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474699-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yahya-al-zahrani/148170/9", "user": "Abdulaziz999", "ts": 1496847730000, "tid": 148170, "pn": 9}}]}', 1496847730000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m.m.s-ias212', 'stk-m.m.s', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-yzahrani", "n": "أ. يحيى الزهراني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ias 212\nترم 162\n\nالتحضير : كل كلاسين ثلاثه ياخذ التحضير عن الكلاسات الماضيه من مبدأ الامانة . ويسلك للتأخير .\n\nطريقة الشرح : سلايدات واشوفه حلو وماشي على السليبس\n\nالكويزات : ما فيه\n\nالمياجر: كومن\n\nالفاينلات :كومن\n\nالقريد النهائي: A+\n\nالصوت: واضح جدا ماشاءالله\n\nإضافات : فيه برزنتيشن فردي عليه خمس درجات بالاصل , كل الطلاب اشوفهم اخذوا عنده خمسه بمجرد تقديمهم , فيه كم واحد اخذوا بونص درجة عليه .\nعند الدكتور عمل جماعي على قولته اغلب البونص على العمل الجماعي ويختلف من قروب لقروب البونص ومن شخص لشخص بالقروب , انا عطاني درجتين بونص من العمل الجماعي ,\nوعنده 3 محاضرات بثلاث ايام ورا بعض بنص الترم يعرضون فيها البرزنتيشن الفردي اذا ما تبي تعرض بالكلاس يعطيك بونص درجه بمجرد حضورك .\nانا طلعت من عنده بثلاث درجات بونص , وحده من المحاضره المسائية , وثنتين من العمل الجماعي . الماده سهله وهو جزاه الله خير سهلها زياده بالبونص", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474741-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yahya-al-zahrani/148170/10", "user": "M.M.S", "ts": 1496896825000, "tid": 148170, "pn": 10}}]}', 1496896825000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10407-ias212', 'stk-user10407', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-yzahrani", "n": "أ. يحيى الزهراني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS212 -163\nالتحضير : يوميا قبل نهاية الكلاس بالسيريال نمبر ( ما يهتم بالتاخير ) يخصم على كل غياب درجة ( ولا غياب طول السمستر يعطيك درجة بونص )\nطريقة الشرح : من السلايدات\nالكويزات : مافي\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:B\nالصوت: واضح جدا\nإضافات : الكلاس وورك عبارة عن عمل جماعي بسيط جدا ، كل الطلاب ياخذون فل مارك ( كل ما تحسن عملك اخذت بونص زيادة )\nالبونص عند الدكتور يوصل الى خمس درجات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479089-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yahya-al-zahrani/148170/11", "user": "user10407", "ts": 1503399800000, "tid": 148170, "pn": 11}}]}', 1503399800000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_nd_m-ias212', 'stk-m_nd_m', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-yzahrani", "n": "أ. يحيى الزهراني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS212 - T163\nما أضيف كثير على كلام الأخ\n\nشرحه ممتاز… حتى و أنت تذاكر و تقرأ من الكتاب تتذكر كلام الدكتور فتثبت المعلومة أكثر\nما يفضل تحضر بشعبة غير شعبتك\nالدكتور عنده درجتين بونص إضافية تاخذهم إذا حضرت محاضرتين إضافية… بالنسبة لنا وحدة كانت عن المنهج قبل الفاينل (مثل مراجعة عامة) و الثانية كانت عامة و تتكلم عن الأخلاق\nالمشروع عنده عبارة عن نبذة و مسح ميداني و تأثير و كل ما كان الشغل أفضل كل ما زاد البونص الجماعي… و بعدين يوزع أوراق على أعضاء المجموعة و يوزعون البونص برأيهم على حسب الأفضلية\nسريع بإرسال الدرجات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479255-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yahya-al-zahrani/148170/12", "user": "M_nd_m", "ts": 1503580470000, "tid": 148170, "pn": 12}}]}', 1503580470000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-walo0od-ias212', 'stk-walo0od', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-yzahrani", "n": "أ. يحيى الزهراني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 - T171\n\nالتحضير:\nنهاية الكلاس بالرقم التسلسلي.\nتقدر تحضر مع شعبة ثانية.\nطريقة الشرح:\nيجيب معاه سلايدات بس غالباً يشرح من نفسه ويحب يتفاعل معاه الطلاب وتكون المحاضرة نقاشية أكثر.\nالكويزات:\nما فيه كويزات. توزيع الدرجات في الأسفل.\nمياجر + فاينل:\nمشتركة\nالقريد النهائي:\nA+ وبكل جدارة\nالصوت:\nواضح جداً ويتكلم بالعربي الفصيح.\nتوزيع الدرجات:\n5%: حضور (خصم درجة واحدة لكل غياب بدون عذر).\n10%:\nالعمل الجماعي:\nمجموعة مكونة من 4 طلاب تشتغلون على موضوع تختارونه بداية الترم ويكون فيه توعية للمجتمع الجامعي.\nمقسم إلى ثلاثة أقسام: قياس الواقع (استبيان أو مقابلات أو غيرها) ثم التأثير (شيء يساهم في التوعية على موضوعكم) وأخيراً عرض تقديمي لكل اللي سويتوه.\n5%: المشاركة في الفصل (مشاركتين = درجة) وإذا وصلت 11 مشاركة يعطيك بونص درجة (يعني 6 من 5).\nإضافات:\n- الدكتور أخلاقه عالية جداً وطيب مع الطلاب ومتعاون.\n- يعطي بونص على العمل الجماعي حسب مدى الإبداع في التأثير اللي سويتوه.\n- ممكن يكون العمل الجماعي أحياناً قروشة، بس هو أفضل من الكويزات بكثير.\n- يقول الدكتور بعض الطلاب يجون يطلبوني أزودهم درجات (مثلاً يسوون بحث ويزودهم) بس أرفضهم لأن مو من العدل أعطيهم فرصة والطلاب الباقين لا.\nهذي نقطة مهمة - لا تتوقع بيزودك أنت لحالك بس عشان ظروفك (بس أساساً بونص العمل الجماعي والمشاركة يكفيك).", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485843-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yahya-al-zahrani/148170/13", "user": "Walo0od", "ts": 1515517502000, "tid": 148170, "pn": 13}}]}', 1515517502000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sadguts-ias212', 'stk-sadguts', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-enaizan", "n": "د. أحمد العنيزان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS212 - 211\nالدكتور احمد العنيزان اسطورة الله يسعده ويوفقه وين ماكان\nاذا شفت اسمه في الكورس اوفرنق نزل المادة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533782-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-enaizan/148171/11", "user": "SadGuts", "ts": 1645339913000, "tid": 148171, "pn": 11}}]}', 1645339913000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-zoroo-ias212', 'stk-zoroo', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khushaim", "n": "د. فهد الخشيم الدوسري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "إسلامي 212 الترم 122\n\nرجل محترم ومثقف في بداية الترم كان يحاسب على التاخر ثم خف بعدها، في نهاية الترم يعطي درجتين بونص والاب قريد عنده من درجة…\n\nفي النهاية ودي اقول ان الرجال هذا من احسن من قابلت في الجامعة واتمنى انزل عنده مواد ثانية…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1255107-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fahad-alkhushaim-al-dosssary/148173/2", "user": "zoroo", "ts": 1377373815000, "tid": 148173, "pn": 2}}]}', 1377373815000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12191-ias212', 'stk-user12191', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khushaim", "n": "د. فهد الخشيم الدوسري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS212- TERM222\nالتحضير :\nفي بداية الكلاس ينادي بالأسماء. ما يحاسب على التأخير.\nطريقة الشرح :\nيتناقش مع الطلاب حول موضوع الدرس وياخذ ويعطي معهم ، وفي حال في نقطة ماكانت واضحة يشرحها.\nالكويزات :\nلايوجد\nالصوت:\nواضح جدًا\nإضافات:\nيطلب من الطلاب في أول فصل سرد قصة من سيرة النبي صلى الله عليه وسلم أو من عهد الخلفاء الراشدين حول موضوع الدرس المفترض اخذه في نفس اليوم ، وعرض تقديمي في آخر الفصل. لا تتردد في أن يكون هو خيارك الأول في حال كان يدرس المادة.\nالقريد النهائي:\n+A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536867-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fahad-alkhushaim-al-dosssary/148173/9", "user": "user12191", "ts": 1692743571000, "tid": 148173, "pn": 9}}]}', 1692743571000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12137-ias212', 'stk-user12137', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khushaim", "n": "د. فهد الخشيم الدوسري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS212- TERM222\nالتحضير :\nالدكتور يتأخر 5 دقائق دائما عن الكلاس والتحضير في بداية الكلاس ينادي بالأسماء. ما يحاسب على التأخير.\nطريقة الشرح :\nكلاسه جدا جدا ممتع ومبني على الحوار بينكم وبينه, أحيانا ما يعطيك نتيجة الحوار لتفكر فيها أنت بنفسك, وأحيانا يعطيك كم سالفة صارت له على السريع, واذا انتهى قبل الوقت يطلعكم لو باقي نص ساعة وفي رمضان الكلاسات خلاها اونلاين لنا وكانت مدتها جدا قصيرة\nالكويزات :\nلايوجد\nالصوت:\nواضح جدًا\nإضافات:\n-البونصات بالهبل تجيك ولا 7 بونصات توصل, الظاهر في منهم بونصين اذا ما غبت طول الترم وأنا غبت ولا 3 مرات وحصلتها\n-البريزنتيشن يكون في قروب من 3 الى 4 وما يأخذ وقت تقريبا بس 5 دقائق تكفي لتسويه (هو قال ما اهتم بالشكل لو تقعد عليه 3 دقائق ولا ساعة) وأنا سويت الي قاله وقدمنا العرض كمجموعة في 4 دقائق وحصلنا فل مارك فيها , جدا متساهل ما شاء الله عليه\n-في مهمة لازم تسويها انك تجيب قصة من السية او الصحابة وتقولها بداية الكلاس (بس سريع سريع بحث ابو دقيقة عن الموضوع وطرح القصة في دقيقة عن الموضوع والسلام عليكم)\n-أحسن مدرس ممكن تنزل عنده اي مادة من هالديبارتمنت ومن افضل من درسني\nالقريد النهائي:\n+A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536921-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fahad-alkhushaim-al-dosssary/148173/10", "user": "user12137", "ts": 1693317170000, "tid": 148173, "pn": 10}}]}', 1693317170000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ak-95-ias212', 'stk-ak-95', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khaldi", "n": "د. عبدالرحمن الخالدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS-212 term 152\n\nالتحضير :\nبداية كل كلاس ينادي على الأسماء، وقليل ما يحط ليت\n\nطريقة الشرح :\nكان يقول إنه زهق من كثر ما يشرح من السلايدات 😂، بالتالي وزع الطلاب مجموعات ، وخلى كل مجموعة تشرح وحدة من الوحدات، وهو بس يعطي تعليقات وإضافات.\n\nالقريد النهائي:\nA+\n\nالصوت:\nواضح واللغة مفهومة\n\nإضافات :\nطيب وأخلاق ، خرج عن النمط القليدي في الشرح ، وخلى تقريبًا كل الشغل على الطلاب 😅، فيه شرح ومشاريع على المجموعات، وورش عمل ، بالتالي صار الكلاس تفاعلي\nطبعا هي إيجابية من ناحية تفاعل الكلاس وأيضا الدرجات،بس يمكن تكون سلبية للي ما يبغى يشتغل شي ، مع ذلك أشوف إن طلباته بسيطة ويعطيك خبر من أول السمستر عشان تجهز نفسك\n\nإذا كنت تبغى تضمن القريد نزل معاه 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1454554-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-khaldi/148174/19", "user": "AK-95", "ts": 1469793217000, "tid": 148174, "pn": 19}}]}', 1469793217000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hammmod-ias212', 'stk-hammmod', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khaldi", "n": "د. عبدالرحمن الخالدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم : IAS 212 Term 161\n\nالتحضير : يوميا أول الكلاس وعادي يعطيك فرصة 5 دقايق تتأخر بدون ما يحسبك ليت.\nطريقة الشرح : يخلي الطلاب يشرحون من سلايداته ويجلس آخر الكلاس واذا فيه نقطة أثارته يوقف الطالب ويقعد يسولف. عن نفسي أشوفه ممل بشكل غير معقول، والله كلاسه طفش وما فيه أي فائدة ولا متعة، حتى أسلوبه وتعامله والله تحس انك في صف رابع. أبدا ما يعجبني، ندمت اني حاطه أول كلاس يخرب حماسي لباقي اليوم.\nالكويزات : ماكو\nالمياجر: ميدترم واحد و كومون\nالفاينلات :\nالقريد النهائي: C\nالصوت: واضح\nإضافات: ميزاته هي البونص اللي يعطيك وما يشغلك برا الكلاس أبد وما نزلت عنده الا عشانها، بدون البونص يمكن أعطيه D.\nمشاكلي معه:\n*من أول يوم يقتل الابداع في الكلاس. يقول كل طالب أو كل مجموعة لازم تشرح درس والشرح بسيط أبد اقرا السلايدات شوي في البيت وأنت منسدح واشرحه في خمس دقايق وخلاص. فتشوف كل اللي يشرحون المنهج يشرحونه بشكل ممل وبس يقرأ الكلام من السلايدات ويتأتئ فيه. جزاه الله خير يسهل عالطلاب لكن المفروض يقول اللي يكون شرحه ممتع ومحضر له بأعطيه على حسب إبداعه، لأن كذا الكلاس صار ممل.\n* يقاطع كثيييير، أوكي في شرح المنهج ممكن يكون مقبول، لكن فيه شروحات كتب يختارونها الطلاب، يقاطع الطالب أثناء الشرح ويقعد ربع ساعة يسولف والطالب ما يزال واقف زي المزهرية، طيب مهوب أنت اللي بتشرح الطالب اللي يشرح. خله يخلص الشرح كامل بعدين علق من عندك.\n* سوالفه مملة وأسلوبه طفولي وبعضها واضح ان فيها نصب. كل كلاس أول ما يجي الصبح يقول نكتة سامجة ومحد يضحك يقول ههههه شكلكم نايمين للحين ههههه شف عيونكم ههههه الظاهر ما تصحصحون الا الساعة 11 هههه.\n* مرتين يغيب بدون ما يعلمنا ونجي للكلاس الساعة 7 وما نلقاه، طبعا ما يعتذر ولا شيء. واللي قاهرني أكثر قد قالوا له الطلاب اللي ساكنين برا السكن أول الترم عطنا فرصة نتأخر شوي لأن الكلاس بدري والدنيا زحمة، قال لا مشكلتك اطلع من بيتك بدري واحسب حساب أي ظرف!!!!\n\nباختصار نسبة الاحترافية 0%", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1465065-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-khaldi/148174/21", "user": "hAmMmOd", "ts": 1482417337000, "tid": 148174, "pn": 21}}]}', 1482417337000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.a1-ias212', 'stk-mr.a1', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khaldi", "n": "د. عبدالرحمن الخالدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 161 IAS 212\n\nالتحضير :\nبداية كل محاضرة. يفتح الكشف على البروجيكتر وينادي بالاسماء.\nياخذ فترة بسيطة لين يحفظ الطلاب مضبوط ويحضّر بالنظر.\nمتساهل مع التأخير اشوي ، بس لا تمصخها وتتأخر وقت طويل من بداية المحاضرة.\nيسمح بالميك أب.\n\nطريقة الشرح :\nمقسّم المنهج على الطلاب (قروبات) ، في وسط الشرح ممكن يوقف ويعلّق أو يضيف معلومات من عنده.\n\nالكويزات :\n-\n\nالمياجر:\nميدترم كومون.\n\nالفاينلات :\nكومون\n\nالقريد النهائي:\n+A\n\nالصوت:\nواضح جدا.\n\nإضافات :\nتعامله أخوي مع الطلاب ، ويمزح معاهم وياخذ ويعطي كثير.\nالدكتور عنده بونص طبعا ، هو مقسم درجة الأنشطة بطريقة معينة ، بحيث لو نفذت كل الأشياء المطلوبة منك تحصل على درجة فوق الـ ٣٠ المطلوبة للانشطة الصفية. طبعا هذه الأشياء أغلبها مع قروبك (شرح جزء من المادة ، تلخيص كتاب أو جزء منه ثم تقديمه ، اختيار شركة وتقييمها أخلاقيا) ، بالإضافة إلى درجتين إضافية للطالب المواظب في حضوره.\nيسوي مسابقات بين الطلاب (يقسمهم على قروبات ويسويها) ، والهدف منها هو إثراء نقطة معينة في أخلاقيات المهنة حتى يستفيد منها الطلاب ، والقروب الفائز في المسابقة يحصل على درجات مشاركة إضافية.\nيلغي كلاسات كثيرة ، إما بغرض إعطاء الطلاب فرصة للعمل على التلخيص وتقييم الشركة ، أو لأغراض أخرى.\n\nباختصار ، د. عبدالرحمن الخالدي رائع جدا ، وأنصح أي شخص بياخذ المادة إنه يسجلها معه. لكن ، لو ما كنت تحب نظام الكلاس التفاعلي ، فما أنصحك ؛ لأنك راح تحسه كرف وما راح يعجبك الوضع.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466021-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-khaldi/148174/22", "user": "Mr.A1", "ts": 1483991969000, "tid": 148174, "pn": 22}}]}', 1483991969000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bo_rayan-ias212', 'stk-bo_rayan', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khaldi", "n": "د. عبدالرحمن الخالدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS212 T161\n\nالتحضير\nكل يوم بداية الحصة، تتأخر يسجلك متأخر ولو تكرر يحسب لك غياب\n\nطريقة الشرح\nما يشرح، يقسم الطلاب بداية الترم ويخليهم يشرحون، نهاية السمستر سمعنا كلام بالعربي شرحكم مخيس وهو صادق 🙂\n\nالكويزات\nمافي كويزات، أعمال السنة كانت عبارة عن شرح درس + تلخيص كتاب + تقييم شركة، تسويها وتاخذ بونص\nتحضر دورة يعطيك بونص\nمجموعتك تفوز يعطيك بونص\n\nالمياجر\nكومون\n\nالفاينلات\nكومون\n\nالقريد النهائي\nأعطيه A\n\nالصوت\nواضح جدا والمواضيع الي يفتحها حلوة\n\nإضافات\nيعامل كل الطلاب كنهم أولاده،\nإذا نزلت معه تأكد انه بيكون فيه شغل، م حتاخذ بونص ع المستريح\nفي شي واحد ما عجبني، أنه يمدح واجد ويسلك لكل الطلاب حتى لو كانوا سيئين\nلكن فعلا انطبق المثل “من أمن العقوبة أساء الأدب”. أكثر الطلاب عرضهم جدا سيء ولا فيه أي جهد (لا أزكي نفسي) لأنهم ضامنين الدرجة سواء أدائهم كان كويس أو لا\nلو أن هذا العرض كان في قسم الطالب كان تشرشح قدام الطلاب لأن غالبا الدكاترة ما يجاملون أبداً\n\nإذا ودك قريد ع المستريح وبدون تعب يمكن لو تشوف غيره أفضل\nأما إذا ودك تستفيد وتفيد فدكتور خالد جدا ممتاز وبيعطيك A+ إذا كنت جاد شوي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466700-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-khaldi/148174/23", "user": "Bo_Rayan", "ts": 1485001173000, "tid": 148174, "pn": 23}}]}', 1485001173000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mkd-ias212', 'stk-mkd', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khaldi", "n": "د. عبدالرحمن الخالدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 - 161\n\nبإختصار : شديد عالحضور والغياب ، يحضّر الطلاب أحيانا بدية الكلاس وأحيانا بعد ما يبدى بخمس دقايق ( تتاخر واجد لا تنزل عنده ) ويعطي بونص للي ما عنده ولا غياب ولا تاخير\n\nبونص بالهبل لكن تحتاج تشتغل صح ( تشرح درس من المنهج + تقدم تلخيص كتاب + تحضر دورات + مسابقات داخل الكلاس ) ، بيشرح لكم بداية الترم كل شي وأنت انتبه لكلامه وسو كل اللي يبيه وبيجيك بونص كويس إن شاء الله\n\nوصدقني بالاسلامي هذا تحتاج بونص بشكل كبير لأنه أصعب من الأول\n\nبالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466719-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-khaldi/148174/24", "user": "MKD", "ts": 1485017806000, "tid": 148174, "pn": 24}}]}', 1485017806000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-azzubair-ias212', 'stk-azzubair', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khaldi", "n": "د. عبدالرحمن الخالدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 term 161\n\nالتحضير : كل محاضرة\nطريقة الشرح :يوزع الطلاب على مجموعات كل مجموعة 3 طلاب تقريبا ويطلب 3 اشياء : شرح جزء من المنهج + شرح كتاب من خارج المنهج لكن يتعلق بأخلاقيات المهنة + استبيان عن شركة تختارها المجموعة\nتوزيع المهام يكون بين طلاب المجموعة وما يتدخل فيه يعني لو طالب واحد يسوي هالثلاث اشياء بيعطيهم الدرجة\nالكويزات : ما عنده كويزات ولا واجبات بس المهام حقت المجموعه ويسوي مسابقات عليها بونص\nيسمح بالميك اب اذا عندك سبب ويكنسل كثير من محاضراته اصلا\nصح انه ما يشرح ابدااا والمادة غثيثة شوي لكن يعطي بونص بزياااادة والبونص يضيفه على المجموع النهائي مو على الكلاس وورك بس\n\nمدرس رهيب وخلوق وطيب وانصح فيه بشدة\n\nالقريد النهائي:ِA+++++", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467649-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-khaldi/148174/25", "user": "azzubair", "ts": 1486288861000, "tid": 148174, "pn": 25}}]}', 1486288861000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tryagain-ias212', 'stk-tryagain', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khaldi", "n": "د. عبدالرحمن الخالدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 - Term 162\n\nالدكتور: عبد الرحمن الخالدي\n\nالتحضير: بداية كل حصة ويعطي فرصة 5 دقايق وبعدها ليت\nطريقة الشرح: الدكتور ما يشرح يوزع الطلاب كل حصة مجموعات مختلفة ويخلي مجموعة من المجموعات الثابتة تقسم الدرس بينكم وكل مجموعة تطلع تتكلم بدقيقتين عن جزئية معينة وبس …\nفي بداية الترم رح يقسمكم إلى مجموعات ثابتة غير المجموعات اللي بكل كلاس … وكل مجموعة مطلوب منها تسوي 3 أشياء … استبيان عن الشركة وتلخيص كتاب وتحضير الدرس عشان تقسمه على المجموعات … طبعاً درجات الثلاث نشاطات هذي اتوقع انها 30 وأعمال السنة كانت 20 ففي عندك بونص 10 درجات تشمل الاختبارات كمان … يعني لو نقصت في الاختبارات العشرة هذي تزيدك …\n\nالحصة للأمانة كانت ملل شوي بالإضافة إلى إنو الجلوس على الجوال عنده ممنوع … لكن ميزة البونص عند الدكتور كافية عشان تخليه الأفضل وخصوصاً إنو 212 أصعب كورس اسلامي وتحتاج فيه بونصات بشكل أكيد\n\nالبونصات عنده كالتالي :\n- تفوز مجموعتك في شرح الدرس ياخذ كل عضو درجة … أقصى حد للدرجات هي 5 بعدها حتى لو فازت مجموعتك مارح تاخذ أكثر\n- تحضر محاضرة تاخذ بونص\n- وتسوي كل النشاطات تاخذ بونص\n\nمافي كويزات عند الدكتور\n\nللأمانة أنا كنت منزعج من بعض التصرفات …\nأولاً : الكلاس كان بـ 24 بداية الترم … وانا كنت مرتب جدولي عشان يكون كله بـ 22 و 24 … أول اسبوعين داومنا بـ 24 بعدها ارسل رسالة مفاجئة إن الكلاس رح يكون من يوم ورايح في 63 والمشكلة المحاضرة اللي بعد الاسلامي كانت بـ 24 يعني مشوار محترم … كلمنا الدكتور ورفض يعدل المكان بحجة إن الكلاس بـ 63 أكبر وأفضل وهو فعلاً أفضل لكن كذا خرب عليك جدولك …\n\nثانياً : في مرة من المرات تأخر 10 دقايق فمشينا وانا وصلت لـ 24 … ارسل تنبيه تقريباً بعد 5 دقايق إنو انا جيت ولو ما حضرت رح يخصم عليك غياب … كان صعب علي إني أرجع 63 مرة ثانية ومارضي الدكتور يشيل الغياب.\n\nالدكتور ممتاز وانصح فيه بكل تأكيد والبونصات عنده كافية إنها تغطي على كل عيوب الدكتوربالإضافة إلى إن تعامله مع الطلاب ممتاز", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474765-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-khaldi/148174/26", "user": "TryAgain", "ts": 1496930514000, "tid": 148174, "pn": 26}}]}', 1496930514000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m7med_21-ias212', 'stk-m7med_21', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khaldi", "n": "د. عبدالرحمن الخالدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "172-IAS212\nالتحضير :\nكل حصة يحضر بداية الكلاس مرن نوعا ما\nطريقة الشرح :\nالكلاس تفاعلي يعني يقسمكم قروبات والوضع مناقشات\nالمياجر :\nكومون\nالفاينلات :\nكمون\nالصوت :\nواضح جدا\nاضافات :\nالدكتور جدا محترم وجدا اخلاق وتعامله مع الطلاب رائع\nانسان فاهم جدا\nالبونص عنده بالكريك زي ما يقولون !\nيعني بدون مبالغة تصل الى 15 بونص غير كرمه !\nسجل عنده وانت مغمض", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492430-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-khaldi/148174/28", "user": "M7med_21", "ts": 1526398245000, "tid": 148174, "pn": 28}}]}', 1526398245000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jafar_15-ias212', 'stk-jafar_15', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khaldi", "n": "د. عبدالرحمن الخالدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212- 181\n\nالتحضير :\nتحضير يومي ، ويدقق على اللي يتاخر بشكل كبير\nطريقة الشرح :\nالدكتور مايشرح، يقسم الوحدات على الطلاب بعد مايقسمهم الى مجموعات\nوكل مجموعة تلخص وحدتها في اوراق وتوزعها على الطلاب كمجموعات متغيرة كل مرة وكل مجموعة يطلع منها واحد يتكلم عن نقطته، وهذي تعتبر المسابقة\nوالدكتور يعلق على بعض النقاط اذا استدعت الحاجة\nالكويزات :\nمافي\n\nالمياجر :\nمدترم وهو كومن\n\nالفاينلات :\nكومن\n\nالصوت :\nواضح جدًا\n\nإضافات :\nالبونص عنده تقدر تحصله ويوصل الى قريدين عادي\nطريقته في البونص يكون نص درجة للفريق الفايز في المسابقات ، واخر الترم يكون درجة لكل فريق لان يكون الفريق العدد فيه اكبر\nوايضا عنده بونص درجتين للي ماعنده غياب ، وكحد اقصى 5 درجات محاضرات مركز التميز الطلابي تحضرها خلال الفصل او دورات معتمدة من مركز التميز الطلابي\n\nبأختصار الدكتور يكرف على خفيف ، لكن بشكل عام الرجال طيب وحبوب ويدف شوي.\nأنصح فيه…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504106-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-khaldi/148174/31", "user": "Jafar_15", "ts": 1545824062000, "tid": 148174, "pn": 31}}]}', 1545824062000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-salman_al-ghamdi-ias212', 'stk-salman_al-ghamdi', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khaldi", "n": "د. عبدالرحمن الخالدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS212-201\nترم اونلاين\n\nالتحضير : بداية الكلاس، يفتح ملف الاكسل وينادي على اسمك مرة ثم يرجع لك لما يخلص تحضير وينادي مرة ثانية، ما جيت؟ خلاص غايب ولو جيت بعدين اظن يحطك متأخر.\nطريقة الشرح : ؟؟؟ ما فيه شرح :)، يقول للطلاب كل واحد يجهز شرحه واطلعوا اقراوا اي شي من تجهيزكم وبعطيكم الدرجة. الدكتور يسوي كذا عشان يضمن ان الكل سوى شي عالأقل ويقدر يعطيه درجات، لكنها صراحة تخلي الوضع ممل جدا جدا جدا جدا جدا جدا جدا جدا جدا جدا جدا جدا جدا جدا جدا جدا. انا اكتشفت وقته انه بالنسبة لي، مواد عربي\\اسلامي افضل انه الدكتور يشرح\\يسولف على انه طالب يطلع بشغل نص كم (واللي هو الغالب وهذا اللي مخيس الموضوع)\nالكويزات : لا يوجد\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: IC (لأنني ما شفت من الدكتور شي برا البونصات صراحة)\nالصوت: كويس\nإضافات : الدكتور يعني معاملته جيدة لنا، لكن صراحة ما شفت منه حاجات كثير عشان اقدر “اقيمه”، لكن هنا في الاضافات بتكلم عن الكلاس وجوه بشكل عام في الاونلاين عشان الكل يكون عنده فكرة. الكلاس يبدأ بالتحضير وياخذ 5 دقايق، ثم يبدأ الدكتور يقول يلا مجموعة رقم كذا ابدأوا، وطبعا ما فيه جدول واضح للمجموعات وتقسيمها فيعني جهز شغلك يمكن يكون الدور عليك، وطبعا المجموعات تبدأ تشرح ويرسلون رابط Microsoft Forms عشان بقية الطلاب يحلون اسئلة مبنية على شرح المجموعة نفسها… الدكتور طلب من كل مجموعة ان الاسئلة تكون واضحة في السلايدات عشان الكل يقدر يجاوب. لكن المشكلة ان الطلاب غالبا يا يكون شرحهم نايم وتأدية واجب (وأقل من تأدية واجب)، يا تكون اسئلتهم مرررررررررررررة صعبة وبين السطور، يا ياخذون الوقت كله ويتفلسفون وما يخلون المجموعات الباقية تشرح، وقلييييييل مرة اللي يكون شرحهم كويس وفي وقت كافي. وطبعا على هذا الموال طول الترم لين خلص. طبعا المهمات اللي عليك: شرح درس، تلخيص كتاب، تقييم شركة. المهمات مش صعبة بس ثقيلة وتسد النفس شوية ومع كيف الكلاس اصلا طول الترم تحس مالك خلق تسوي اي شي له علاقة بالمادة. طبعا في الاخير الدكتور كويس للي يبغى بونص ويبغى يشتغل بس ما يبغى الدكتور يشرح (مدري ليش في واحد كذا؟؟ بس اوك) ويعني الدكتور ما يرد عليك لا ايميل (معذور لأن ايميله زحمة ومعلق) ولا يرد واتس اب ولا يرد على صندوق بريد البلاكبورد (ليش احد يستعمله اصلا) فيعني تواصلك مع الدكتور يكون فقط وفقط في الكلاس، غير ان البلاكبورد نفسه عشوائي وبالعربي ومليان صفحات مالها داعي وكذا حوسة. فيعني ما بنصح احد ينزل عند الخالدي ويدور له دكتور يعطي بونص أو\\و دكتور يشرح بدون كرف (صدقني ما تبغى الكرف في ذي المادة، يخرب بقية الترم عليك).", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527770-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-khaldi/148174/34", "user": "Salman_Al-Ghamdi", "ts": 1610293119000, "tid": 148174, "pn": 34}}]}', 1610293119000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11724-ias212', 'stk-user11724', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khaldi", "n": "د. عبدالرحمن الخالدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term201 - IAS212\nالتحضير: بداية الكلاس في اكسل ولو تاخرت شوية ما يحطك تاخير او غياب، اذا صارت مشكلة في تاخير او غياب وكلمته يحط علامة عند اسمك ولو كررتها يحسبها الثنتين واذا ما تكررت يمسحها، وكثير من الشباب استفادوا من الحركة هذي.\nطريقة الشرح: الطلاب يكونون متقسمين على مجموعات ويشرحون والدكتور يعلق اذا شاف الموضوع يحتاج تعليق.\nالمياجر: سهلة\nالفاينل: سهل\nالقريد النهائي: A++++\nالصوت: واضح جدا\nإضافات: الدكتور اعطانا 4 او 5 كلاسات اجازة في الترم، والاهم من كذا ان الكلاس وورك ما دقق عليه وكانوا اغلب الطلاب ياخذون فل حتى لو ما يستاهلون، الي ياخذ عنده اقل من A+ يعتبر مقصر جدا، خصوصا انه يعطي ***8 درجات*** بونص، (طريقتها انك تجاوب على 8 اسئلة من شرح الطلاب والمطلوب انك تجيب 6 او اعلى وكل مجموعة تجيب فيها 6 واكثر تاخذ نص درجة واغلب الاسئلة تكون سهلة واغلب الطلاب اخذوها) يعني عندك 13 درجة تغلط فيها ولسا تاخذ A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1528026-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-khaldi/148174/37", "user": "user11724", "ts": 1611177517000, "tid": 148174, "pn": 37}}]}', 1611177517000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dex-ias212', 'stk-dex', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khaldi", "n": "د. عبدالرحمن الخالدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS212- Term211\nالتحضير: بدايه الكلاس ويسجل تأخير بعد ٥ دقايق تقريباً\nطريقة الشرح: بدايه الترم يقسم الطلاب لقروبات وعليهم الشرح … يجلس ورا ويعلق على بعض النقاط الي تستاهل\nالميد : سهل جداً وبتخلصه ب١٠ دقايق\nالفاينل: اصعب من الميد ولكنه سهل بعد\nالقريد النهائي: A++++ وقليله بحقه\nالصوت: واضح جدا\nإضافات: الدكتور حبيييب جداً وتعامله راقي وما شفته يعارض او يسكت او يرفع صوته على اي طالب … ايضاً تقسيمته الكلاس وورك تخليك تقدر تطلع ب٤٩ درجه من ٤٠ يعني عندك ٩ درجات بونص", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533354-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-khaldi/148174/38", "user": "Dex", "ts": 1641578887000, "tid": 148174, "pn": 38}}]}', 1641578887000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-idk-ias212', 'stk-idk', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-khaldi", "n": "د. عبدالرحمن الخالدي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS212 - T242\n\nالتحضير :\nيهتم بالتحضير ويعطيك تاخير بعد خمس دقايق بس بعض المرات يتساهل\n\nطريقة الشرح :\nيخلي الطلاب يسوون 8 مجموعات وكل مجموعة تشرح فصل واحد ووقت شرح الطلاب اذا عنده تعليق يعلق وصراحة يوم يشرح يكون واضح ورهيب\n\nالكويزات :\nيخلي الطلاب الي شرحوهم الي يسوون الكويزات يعني كل مجموعة شرحت يعبون اكسل شيت هومسويها ويحطون الأسئلة ويخير الطلاب كم عدد الكويزات الي يبغونه والكويزات على البلاك بورد\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA+\n\nالصوت:\nواضح\n\nإضافات :\nدكتور رهيب بختصار", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537880-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-khaldi/148174/39", "user": "idk", "ts": 1730825499565, "tid": 148174, "pn": 39}}]}', 1730825499565, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_3abed1-ias212', 'stk-abu_3abed1', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-rharbi", "n": "د. راكان الحربي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 - Term 172\n\nنبذه عن الدكتور: هذا اول سمستر للدكتور راكان في الجامعة ، كان مبتعث في امريكا وحصل على الدكتوراه اعتقد هذه السنة والله العالم.\n\nالتحضير : يحضر بعد عشر دقائق من بداية الحصة وبعدها تعال في اي وقت يحطك متأخر “وليس غايب”\nيقبل الميك اب في الحالات الضرورية ولازم تكون مرسله السبب في الايميل قبل حضورك.\n\nالشرح : طريقة الدكتور في الشرح هي عن طريق باور بوينت يكون مكتوب فيها رؤوس اقلام للدرس ويفصَل فيها خلال الحصة.\nاحيانا يسوي مجموعات يناقشون فيها مشكلة او احد الاخلاقيات المتعلقة بالمادة .\n\nالكويزات: سهلة “جدا” ، تكون في الغالب سطحية وما تتعمق بالمنهج ( كوزياته تركز على الفهم وليس الحفظ … يعني اذا انت تكره الحفظ تتطمن).\n\nالمياجر والفاينلات : يسوي قبلهم مراجعة عامة للاختبار سواءً الميد او الفاينل .\n\nالقريد النهائي : والله من وجهة نظري الشخصية اعطيه “+A” لاسباب عدة منها:\n\n-اولاً: الدكتور حبيب ومتعاون وما يميزه هو روحه الشبابية مما يعطيه القبول عند معظم الطلاب.\n-ثانياً: يخليك متطمن على درجاتك اهم شي شارك وجاوب على اسالته يحس انك متفاعل معاه ودرجاتك في جيبك ما عليك الا تفلح في الميد والفاينل.\n-ثالثاً: كل التصرفات العبيطة لما يسمى “دكتور” مثل الشدة والكبر اللي ماله داعي،لا تجدها في د.راكان بل العكس تجد التواضع والاحترام المتبادل.\n\nالصوت : ما شاء الله واضح ،واقعد في اي مكان بتسمعه\n\nاضافات:\n- اذا كنت من اللي يهتمون بالكتاب ولازم ينشرح لك الكتاب بكل تفاصيله لا تسجل عن د.راكان ، ولكن اذا تحب ربط المواضيع الموجودة في الكتاب بمواضيع اجتماعية ونعايشها في واقعنا فانصحك بالتسجيل عنده ،،،، وفي نهاية المطاف تراها ماهي رياضيات ،، اللي اقصده عطها كم يوم قبل الاختبار واحفظ وادخل اختبر وعيش حياتك .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493695-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rakan-alharbi/179107/3", "user": "Abu_3abed1", "ts": 1528105850000, "tid": 179107, "pn": 3}}]}', 1528105850000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bmm-ias212', 'stk-bmm', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-rharbi", "n": "د. راكان الحربي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 - Term173\nالتحضير : يحضر آخر 10 دقايق وعادي تدخل متأخر مايقول لك شيء\nالشرح : الدكتور ابدا مايتطرق للكتاب وتحس انه يتكلم عن منهج ثاني. وجهة نظر الدكتور يقول (( ليش اشرحلك تعاريف وايات وهي موجودة في الكتاب تقدر تحفظها وتختبر وتجيب فل مارك)). وهذا الشيء خلى الكورس ممتع\nباختصار : الدكتور يحاول يربط المنهج (( أخلاقيات المهنة )) بالواقع وهذا يخلي الكلاس ممتع جدأ.\nالمراجعه : الدكتور يعمل مراجعه سريعه قبل المد والفاينل وكل الي عليك انك تقرا الكتاب وتحل اولد اقزام .\nالبونص: البونص عند الدكتور بالهبل . اذكر زاد كل طالب في المد درجتين +وفي الفاينال درجة + بونص خاص من عنده للطلاب المشاركين.\nالكوزات : تافه جدا كويزين فقط.\nالهوموركات : سهله جدا هوموركين فقط.\n\nخلاصه:\nالدكتور رهيب جدا كلاسه ممتع للغاية ، انصحك اننك تستمتع معاه في الكلاس وقبل الميد بيومين اقرا الكتاب وحل اولد أقزام.\n((أهم شيء عند الدكتور المشاركة ))", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498223-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rakan-alharbi/179107/4", "user": "BMM", "ts": 1535372606000, "tid": 179107, "pn": 4}}]}', 1535372606000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sultan_salman_1419-ias212', 'stk-sultan_salman_1419', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-rharbi", "n": "د. راكان الحربي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 - TERM 182\n\n1- يحضر في أخر الحصة\n\n2- شرحه والمواد اللي يناقشها معك مختلفة جزئيا عن اللي موجود في الكتاب … بتستفيد منه في الcase studies والassignments والكويزات … بس ما راح تستفيد منه بشكل كبير في المياجر والفاينل … طبعا شرحه حلو وممتع ويعطيك أمثلة موجودة في الواقع\n\n3- كويزاته من السلايدات … سهلة\n\n4- المياجر ذاكر من الكتاب وأمورك تمام … عموما الدكتور اخر كلاس قبل الميجر بيعطيكم مراجعة عن الاشياء اللي بتجي في الميجر … من سهل إلى متوسط\n\n5- نفس الكلام بالنسبة للفاينل … من سهل إلى متوسط\n\n6- أعطيه B+\n\n7- صوته مسموع بس أجلس قدام أحسن\n\n8- كأخلاق الدكتور محترم … بالنسبة للبونص ركز على المشاركة بالكلاس … شارك بأقصى ما تقدر عشان يعرفك … الA+ يبيلها شغل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509270-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rakan-alharbi/179107/9", "user": "sultan_salman_1419", "ts": 1556777037000, "tid": 179107, "pn": 9}}]}', 1556777037000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fhd-ias212', 'stk-fhd', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-rharbi", "n": "د. راكان الحربي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 - TERM 192\nالتحضير : يوم بيوم\nطريقة الشرح: سلايدات غير عن الكتاب … يشرح منها اهم الاشياء اللي بالمنهج.\nالكويزات : سهل\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:A+\nالصوت: واضح\nإضافات : الدكتور كويس وانصح فيه وبشده … متعاون جدا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522554-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rakan-alharbi/179107/13", "user": "FHD", "ts": 1591094640000, "tid": 179107, "pn": 13}}]}', 1591094640000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar_ali_bajabaau-ias212', 'stk-omar_ali_bajabaau', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-rharbi", "n": "د. راكان الحربي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 - TERM 192\nالنصف الثاني من الترم صار اونلاين\n\nالتحضير : ينادي الاسماء نهاية الكلاس واذا تاخرت احيانا يمشيها لك بس لاز تكون صادق معه وبيضبطك\n\nطريقة الشرح : الي حلو انه شرحه عبارة عن اشياء تفيدك من الواقع ومايشرح اي شيء من الكتاب لانه يقول الكتاب عندك وتقدر تقراه وتروح للاختبار.\n\nالتصحيح: بالنسبة للمشروع كان تصحيحه حلو\n\nالكويزات :كويزات بسيطة ع البلاكبورد بس ممكن فيها تريكات ولازم تركز\n\nالمياجر:ميد وكان فيها شوية تريكات\n\nالفاينلات :كان ع البلاكبورد وبرضو فيها تريكات ويبغالك تنتبه، بس بالمجمل كان سهل الى متوسط\n\nالصوت: واضح ورااااايق\n\nإضافات : الدكتور ماشاء الله عليه اسلوب وانيق وحبيب ويحببك في الكلاس والمشاركة وتستمتع في الكلاس معاه، انا ماقد استمتعت في كلاس اسلامي او عربي زي مااستمتعت مع الدكتور ركان، ودك مايخلص كلاسه. ماعنده بونص لانه يعتبره اهانة للطالب، واذا انت تقدر تشتغل معاه وتسوي الي يطلبه انصحه وبشدة، لكن اذا تبغا دكتور مايطلب اشياء ويريحك شوف غير ركان. انا عن نفسي رح انزل عند ركان اذا لقيته في اي مادة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527735-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rakan-alharbi/179107/14", "user": "Omar_Ali_BajabaaU", "ts": 1610194286000, "tid": 179107, "pn": 14}}]}', 1610194286000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10610-ias212', 'stk-user10610', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-shebl", "n": "د. رامي الشبل", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212-181\n\nدكتور حبيب وأخلاق .\n\n--في الشرح معه الكتاب ويسولف مع الكلاس ويحاول أننا حنا نجيب الدرس ونفهمه . يعني مثال عندنا موضوع الأخلاق , يقول يالله وش تعرفون عن الأخلاق ونقول حنا مثلا 10 أدلة من الكتاب والسنة يعني نسوي عصف ذهني ثم يبدأ يشرح ويناقش اللي قلناه . بالطريقة هذي تكون منتبه مع الدكتور وعارف الدرس والأمثلة حتى لو ما ذاكرت, وفي نفس الوقت تجمع درجات مشاركة اذا كنت تشارك معه في العصف الذهني --\n\nطبعا قبل شوي شرحت الشرح ! 😕 😕\n\nلكن بإختصار الكلاس كله حلو وخفيف كله يروح سوالف ونقاش مع الدكتور وسوالف حلوة ومفيدة .\nبالنسبة للبونص فيه محاضرات تجي في الليل , يقول أحضروها وسووا ملخص وأرسلوا لي بالايميل + المشاركة معه في الكلاس= امورك تماااااام .\n\nوالميكأب عنده سهل جدا وهو متساااااااهل جدا يعني أحضر اي كلاسين في الاسبوع وكثر خيرك ( اي كلاس اي وقت ! )\n\nفي النهاية يعتبر خيار اسطوري جدا ! نزل وانت مغمض", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503898-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ramy-alshebl/180680/2", "user": "user10610", "ts": 1545465203000, "tid": 180680, "pn": 2}}]}', 1545465203000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bader_alqahtani-ias212', 'stk-bader_alqahtani', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-shebl", "n": "د. رامي الشبل", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ias212-181\nالشرح :يشرح من الكتاب كلاسة ممتع و يفتح نقاشات مع الطلاب و يتجاوب معهم\n\nالتعامل:تعامل الدكتور اخوي مع الطلاب و يقدر الطالب و يسمح بميك اب طول الترم\n\nالبونص :سوالنا كوز من ٩ درجات هي بونص لكل طالب\nالكلاس ورك ؛م طلب من الطلاب اي حاجة لا كوزات ولا برزنتيشن يوزع درجات من كيفه و الشي ذا ظالم جدا عطاني قريد انا استحق اكثر منه بسبب توزيعه العشوائي لدرجات اظافك الى انه انسان مو واضح يوعد بشي و م يسويه\nصراحة م انصح فيه لانه فيه احسن منه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513377-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ramy-alshebl/180680/5", "user": "Bader_Alqahtani", "ts": 1565020530000, "tid": 180680, "pn": 5}}]}', 1565020530000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_mag-ias212', 'stk-mohammed_mag', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-aomar", "n": "د. أحمد العمر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 -202\n\nالتحضير :\nتلقائي بلاكبورد من السستم نفسه , واذا وضحتله سبب غيابك مايقصر .\n\nطريقة الشرح :\nيشرح المواضيع المتعلقه بالكورس بدون الكتاب , وكان طريقه شرحه ممتعه يعني زي سواليف\n\nالكويزات :\nخذينا كويزين وكانو سهلين نوعا ما\n\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالصوت:\nواضح جدا\n\nإضافات :\nالدكتور أهم شيء عنده المشاركه بالكلاس , يعني اذا جاوبت في اي سؤال أو شاركت بشكل عام , يسألك عن اسمك ويسجله عنده .\nغير كذا الي مايشارك يمكن كل اسبوعين ينادي اساميهم ويقول تراكم مامعكم درجات مشاركه شاركو . يعني اهتمو بالمشاركه عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530009-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-omar/183545/6", "user": "Mohammed_Mag", "ts": 1621500022000, "tid": 183545, "pn": 6}}]}', 1621500022000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-aomab-ias212', 'stk-aomab', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-aomar", "n": "د. أحمد العمر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212 -202\n\nالتحضير :\nتلقائي BB\n5 دقائق يحتسب تاخير\n10 دقائق يحتسب غياب\n(ما فيه غيابات مجانية كله محسوب)\nطريقة الشرح :\nنقاش أكثر من كونه شرح والطريقة كويسه\n\nالكويزات :\nسهله جدا\n\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالصوت:\nواضح\n\nإضافات :\nأكثر من المشاركة قد ما تقدر\nلا تغيب\nبدع في الميد والفاينل قد ما تقدر\n\nA+ في الجيب\n+ الدكتور راح يزبط في النهاية\nخاصة اذا بقي لك 2 على القريد اللي بعده يعطيك بدون نقاش\n\n*انصح فيه وبقوة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530470-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-omar/183545/7", "user": "AOMAB", "ts": 1623372747000, "tid": 183545, "pn": 7}}]}', 1623372747000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulmalik123-ias212', 'stk-abdulmalik123', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-aomar", "n": "د. أحمد العمر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "203 - ias212\nباختصار الدكتور ما يشرح ، يفك الكلاس و يشوف هرجة قريبة من الدرس و يفتحها و ياخذ وجهات النظر و ياخذ و يعطي معاك. لازم تشارك معاه عشان كلاس وورك. ما اعرف كيف الحضوري لكن كلاسه مو متعب ما يشرح ابدا كل كلاسه اخذ و عطى كلام. حطنا بمجموعة و اعطانا ٤ مدري ٣ اسايمنتات كانت خفيفة عشان قسمنا الشغل بيننا بس كان يبغ شغل ومحترم واعطانا بونص عليه و فوقها بونص للي ما عنده غياب وما عطانا كويزات. عموما المادة ما تحتاج شرح. ماهو خيار سيء ولا ممتاز خيار عادي جدا بس يحتاج شغل شوي اذا كان موجود سجل عنده.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531529-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-omar/183545/8", "user": "abdulmalik123", "ts": 1630068470000, "tid": 183545, "pn": 8}}]}', 1630068470000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jolenve-ias212', 'stk-jolenve', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-aomar", "n": "د. أحمد العمر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "term203 - IAS212\n\nالدكتور اسطورة , نزل عنده و انت مغمض !!!!\nالقريد النهائي : A+++++", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1532572-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-omar/183545/9", "user": "Jolenve", "ts": 1635521023000, "tid": 183545, "pn": 9}}]}', 1635521023000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-posty-ias212', 'stk-posty', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-aomar", "n": "د. أحمد العمر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS212-211\nالدكتور احمد العمر\nالتحضير : يحضر اول يومين ف الترم بعدين مايصير يحضر الا اذا الكلاس فاضي\nطريقة الشرح : الماده اصلا سوالف لاكن واعتقد المنهج بيتغير الترم الجاي\nالكويزات : للحين ماعطانا كويزات بس مسوي قروبات من اربع طلاب يسوون برزنتيشن وخلانا نمسك قضية من ديوان المظالم ونتكلم عنها\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:A++\nالصوت:واضح\nإضافات : الدكتور حبيب ومتساعد، يحب انه ياخذ ويعطي مع الطلاب، يعطي بونص كثير وسهل تجيب A+ معه، المنهج على كلام الدكتور انه بيتغير، ف ممكن بعض الاشياء الي قلتها راح تتغير خاصة ان الدكتور متحمس للمنهج الجديد ودايم يذم المنهج القديم، الدكتور يستاهل تخليه خيارك الاول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1532691-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-omar/183545/10", "user": "Posty", "ts": 1636486472000, "tid": 183545, "pn": 10}}]}', 1636486472000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yousef_alamoudi_4507-ias212', 'stk-yousef_alamoudi_4507', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-aomar", "n": "د. أحمد العمر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS212 - Term 211\n\nالتحضير: بداية الكلاس و اللي يتأخر خلال اول 5 دقايق كان يسأله عن السبب عالسريع (في حالتي كنت اقله انه الكلاس اللي قبله الدكتور يطلعنا متأخر 😂).\n\nطريقة الشرح: بداية الترم فتح شوية سلايدات بس بعدين سحب عليها و صار يشرح بدون شيء (الا في اخر السمستر كان يفتح مواقع الانظمة زي حق الخدمة المدنية و غيرها عشان نتناقش في المواد).\n\nالكويزات: ما كان في اي كويز معاه.\n\nالميد: كومن و كان تافه جدددا.\n\nالفاينل: كومن و الله ييسره.\n\nالقريد النهائي: S+ و قليلة مرة بحقه.\n\nالصوت: واضح جدا بس بعض الاحيان يرخي صوته في بعض السواليف.\n\nاضافات: الدكتور حبيب و متساعد و اخلاقه تخجلك صراحة ما شاء الله عليه، يحب يسولف في الكلاس خصوصا وقت المياجر عشان يخفف الاعباء اللي علينا، يطلعنا بدري بعض الاحيان اذا كان الكلاس قصير و خلصنا اللي علينا.\n\nالدكتور عمل حركة المجموعات هذا الترم و كل مجموعة كان عليها عرضين (واحد عن الاخلاق المحمودة و الثاني كان مشروع خفيف لطيف).\n\nاعطى واجبين خلال الترم كلاهما المجموعة تشتغل فيهما.\n\nالقريد العالي جدا سهل عنده بس تحتاج تعمل اللي عليك (من ناحية شغلك مع مجموعتك) و باذن الله الـA+ بالجيب.\n\nزي اللي قال قبلي ذكر انه المنهج احتمال كبير يتغير (ما ادري اذا منجد و لا لا بس تقدر تلاحظ تغير اسم المادة في الاوفرنج في ترم 212 عن الاترام اللي فاتت)، الدكتور عنده تحفظات على الكتاب المستخدم و يطالب بتغييره ( ما الومه صراحة ).\n\nبالنسبة للبونص اعطى درجتين اتوقع على محاضرة ليلية.\n\nلو لقيته انصحك تلحقه قبل ما تلحق.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533138-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-omar/183545/11", "user": "yousef_Alamoudi_4507", "ts": 1640180903000, "tid": 183545, "pn": 11}}]}', 1640180903000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-q18-ias212', 'stk-q18', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-aomar", "n": "د. أحمد العمر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS-212\n211\n- التحضير : مو كل يوم يحضر أحيان يسحب لو الكلاس مليان.\n\n- طريقة الشرح : الدكتور شرحة جميل وخلي المادة ممتعه بحيث أنه مخلي المادة عباره عن نقاشات تسهل الوضع بمراحل عن الكتاب .\n\n- الكويزات :مافيه كويزات.\n\n- المياجر والفاينلات: كومن.\n\n- القريد النهائي :A+\n\n- الصوت : واضح وينفهم.\n\n- إضافات : الدكتور يحب النقاشات ويحب يعرف الطلاب من وجيههم ويحفظ أساميهم بسرعة فحاول يعرفك بسرعة وتشارك معاه وبيكون لك تعامل خاص بالقريد على قولته+ عنده بونص عدم غياب وبونصاته إذا كان شغلكم جميل في البرزنتيشينات وكذه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533392-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-omar/183545/12", "user": "Q18", "ts": 1641839062000, "tid": 183545, "pn": 12}}]}', 1641839062000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr_exceptional_stude-ias212', 'stk-mr_exceptional_stude', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-aomar", "n": "د. أحمد العمر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS212 - Term 212\n\nالتحضير : يحضر من تطبيق اسمه Acadly، تكون محملة واذا حضرت اللكشر من نفسه يربط مع بلوتوث الدكتور ويتأكد من موقعك ويحضرك. صراحة كان حل ذكي، رغم إن بعض الطلاب بنهاية الترم يشتكون منه، لكن لو كنت منتبه لتحضيرك فيه ولو صارت مشكلة تكلم الدكتور على طول بيمشي وضعك. الدكتور ما يعطي أي غياب مجاني (كعادة IAS) لكن يقبل الأعذار الحقيقية. إذا تأخرت (10 دقايق اعتقد) ليت وكل 3 ليت بغياب.\nطريقة الشرح : المادة ما يحتاجلها شرح، قراءة المقرر تكفي وجداً. الدكتور ما يشرح، يسولف في مواضيع حول المنهج وأحياناً برا. بعض الطلاب يشتكون من سواليفه ويمكن فكرتهم إنهم مب جايين عشان سواليف، بس بالنسبة لي الكلاس أمتع كذا من إنه يشرح أشياء بديهية، وبالعكس استفدت من أفكاره.\nالكويزات : فكر يعطينا كويز، ثم ما أعطى. وأعتقد كان بيكون سهل جداً لو أعطى.\nالمياجر: كومن (الميد)\nالفاينلات : كومن\n(الاختبارات بالمادة، وخصوصاً الفاينل، غبية جداً، خلك مستعد لهالشيء، نفس الاستقعاد بأسئلة IAS111 بس بأسئلة غلط وغبية بعد)\nالقريد النهائي: +A\nالصوت: واضح\nإضافات : الدكتور مهتم بتطوير الطلاب، ويحاول يطور مهاراتهم الاجتماعية سواءً بالتدريب بالكلاس أو بالإرشاد النظري، وهذا يحسب له جداً. أعطى بنهاية السمستر بونس حلو مرة. غالباً بيدرس دكتوراة ويرجع يدرس بكلية ثانية، الله يوفقه وأنصح تنزل معه جداً لو لقيته السنين الجاية.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534396-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-omar/183545/13", "user": "Mr_Exceptional_Stude", "ts": 1653315326000, "tid": 183545, "pn": 13}}]}', 1653315326000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-me_student91-ias212', 'stk-me_student91', 'IAS 212', 'doc', '{"docs": [{"id": "stk-dr-aomar", "n": "د. أحمد العمر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 212- TERM 242\nالتحضير : ينادي بالأسماء بداية المحاضرة وأحيانا في النهاية ويسامح في التأخير لمدة قصيرة (5 دقايق أو أقل)\nطريقة الشرح : كلام شفهي وكثير مرات ينقلب سوالف عن نفس الموضوع وإذا ما نبهته بياخذ شوط طويل معك\nالكويزات : ما سوا كويز\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح\nإضافات:\nالواجبات عليها 40 درجة لكن الدكتور ما أعجبه لذلك قرر يعيد توزيع الدرجات شوي وركز على التفاعل معه داخل الكلاس، كريم ويعطي اللي يعطيه ويركز معاه، ما طلبنا أي برزنتيشن ولا شي، قالنا أنه وده يخفف علينا المادة ذي قد ما يقدر وما قصر جزاه الله خير.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1539636-ias212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-omar/183545/14", "user": "ME_STUDENT91", "ts": 1747826173760, "tid": 183545, "pn": 14}}]}', 1747826173760, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
